custom_css:
/* =============================================================================
   APPLE GLASS 2  ·  SillyTavern shell theme (DESIGN.md v1.1)
   Published as the UI theme "Apple Glass 2" by sync-css.sh.

   Scoping rule: EVERY rule in this file hangs under `html body.ag2`. The class is
   added by the AppleGlassStyles extension (shell/index.js) only while this theme
   is active and the URL has no `classic`, so under any other theme — and under
   `?classic` — nothing here applies. When a rule must beat SillyTavern's own
   styles, use `html body.ag2:not(#_):not(#__)` + !important (same trick as
   apple-theme.css).

   Sections follow the design numbering:
     0 · Tokens (§6 visual spec, §7 motion)        ← P0
     1 · Typography (ported from apple-theme.css §1) ← P0
     2 · Layout · 2.1 Shell frame · 3 · Sidebar · 4 · Capsules  ← P1a
     5.8 · Menus · 5.10 · Welcome                    ← P1a
     5.3 · Reading · 5.3b · Chat styles · 5.4 · Input island · 5.4c · + menu  ← P1b
     14 · Accessibility (reduced motion)            ← P0 (token level only)
   ============================================================================= */

/* == 0 · Tokens == */

html body.ag2 {
    /* Fonts: SF Pro / PingFang SC on Apple, Noto Sans CJK on Linux (§6) */
    --ag2-font: -apple-system, BlinkMacSystemFont, "SF Pro Text", "SF Pro Display",
        "Helvetica Neue", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei UI",
        "Microsoft YaHei", "Noto Sans CJK SC", "Noto Sans SC", "Segoe UI", sans-serif,
        "Apple Color Emoji", "Segoe UI Emoji", "Noto Color Emoji";
    --ag2-mono: ui-monospace, "SF Mono", "SFMono-Regular", Menlo, Monaco, Consolas,
        "Noto Sans Mono CJK SC", "Noto Sans Mono", monospace;

    /* Labels l1–l4 */
    --ag2-l1: rgba(255, 255, 255, 0.94);
    --ag2-l2: rgba(235, 235, 245, 0.64);
    --ag2-l3: rgba(235, 235, 245, 0.42);
    --ag2-l4: rgba(235, 235, 245, 0.26);

    /* Fills f1–f5 */
    --ag2-f1: rgba(120, 120, 128, 0.40);
    --ag2-f2: rgba(120, 120, 128, 0.28);
    --ag2-f3: rgba(120, 120, 128, 0.20);
    --ag2-f4: rgba(120, 120, 128, 0.12);
    --ag2-f5: rgba(255, 255, 255, 0.045);

    /* Separators (always drawn 0.5px) */
    --ag2-sep: rgba(255, 255, 255, 0.075);
    --ag2-sep-strong: rgba(255, 255, 255, 0.13);

    /* System colours (dark) */
    --ag2-blue: #0a84ff;
    --ag2-green: #30d158;
    --ag2-orange: #ff9f0a;
    --ag2-red: #ff453a;
    --ag2-purple: #bf5af2;
    --ag2-pink: #ff375f;
    --ag2-teal: #40c8e0;
    --ag2-indigo: #5e5ce6;
    --ag2-graphite: #8e8e93;
    --ag2-quote: #8cc4ff;

    /* Accent: components reference ONLY these three. The appearance page swaps
       --ag2-accent (body[data-ag2-accent=…], P2a); hover/soft derive from it so a
       colour change touches one variable. */
    --ag2-accent: var(--ag2-blue);
    --ag2-accent-hover: color-mix(in srgb, var(--ag2-accent) 82%, white);
    --ag2-accent-soft: color-mix(in srgb, var(--ag2-accent) 20%, transparent);

    /* Materials (§6). Blur values are paired with their surface; small controls
       never blur (§7 budget). */
    --ag2-mat-side: rgba(30, 30, 36, 0.50);      /* sidebar, inspector */
    --ag2-mat-float: rgba(40, 40, 47, 0.56);     /* floating capsules, composer */
    --ag2-mat-window: rgba(28, 28, 33, 0.80);    /* settings window */
    --ag2-mat-menu: rgba(44, 44, 51, 0.82);      /* menus, popovers */
    --ag2-blur-side: saturate(200%) blur(50px);
    --ag2-blur-float: saturate(190%) blur(30px);
    --ag2-blur-window: saturate(190%) blur(50px);
    --ag2-blur-menu: saturate(190%) blur(50px);
    /* fast_ui_mode / body.no-blur: opaque equivalents of the materials above */
    --ag2-solid-side: rgb(30, 30, 36);
    --ag2-solid-float: rgb(40, 40, 47);
    --ag2-solid-window: rgb(28, 28, 33);
    --ag2-solid-menu: rgb(44, 44, 51);

    /* Rim + shadows: every glass surface = rim + one shadow tier */
    --ag2-rim: inset 0 0 0 0.5px rgba(255, 255, 255, 0.13), inset 0 1px 0 rgba(255, 255, 255, 0.09);
    --ag2-sh1: 0 1px 2px rgba(0, 0, 0, 0.28);
    --ag2-sh2: 0 8px 28px rgba(0, 0, 0, 0.30), 0 1px 3px rgba(0, 0, 0, 0.24);
    --ag2-sh3: 0 30px 80px rgba(0, 0, 0, 0.55), 0 8px 22px rgba(0, 0, 0, 0.32);

    /* Radii (concentric: panel 22 = card 16 + 6 inset) */
    --ag2-r-window: 26px;
    --ag2-r-panel: 22px;
    --ag2-r-card: 16px;
    --ag2-r-row: 12px;
    --ag2-r-ctl: 9px;
    --ag2-r-full: 999px;

    /* Spacing: 4pt grid; panels sit 10px from the window edge */
    --ag2-inset: 10px;
    --ag2-pad: 20px;
    --ag2-pad-wide: 28px;
    --ag2-side-w: 292px;
    --ag2-insp-w: 360px;

    /* Type scale (§6): size / weight */
    --ag2-fs-large: 32px;      /* phone large title, 760 */
    --ag2-fs-title: 21px;      /* 720 */
    --ag2-fs-headline: 15px;   /* 650 */
    --ag2-fs-body: 14px;
    --ag2-fs-sub: 13.5px;
    --ag2-fs-foot: 12.5px;
    --ag2-fs-section: 11.5px;  /* 620 */
    --ag2-read-size: 16px;     /* reading body, user-adjustable 14–20 (P2a) */
    --ag2-read-lh: 1.86;
    --ag2-read-ls: 0.012em;
    --ag2-read-width: 720px;

    /* Motion (§7): press 90ms · hover/fade 200ms · panel 280ms, iOS sheet curve.
       Zeroed under reduced motion (§14 below). */
    --ag2-dur-press: 90ms;
    --ag2-dur: 200ms;
    --ag2-dur-panel: 280ms;
    --ag2-ease: cubic-bezier(0.22, 1, 0.36, 1);
    --ag2-ease-sheet: cubic-bezier(0.32, 0.72, 0, 1);

    /* Layers: the shell stays below #top-settings-holder (z 3005, a stacking
       context holding ST's drawers and the right rail) and below ST's legacy
       popups (#character_popup 4001, #shadow_popup 9999) — §9.2 #2 / #10. */
    --ag2-z-shell: 30;
    --ag2-z-capsule: 40;
    --ag2-z-window-backdrop: 3001;
    --ag2-z-window: 3002;
    --ag2-z-menu: 3004;
}

/* No-blur mode: ST's fast_ui_mode adds body.no-blur. Swap materials for opaque
   colours so surfaces built from the tokens stay legible without blur. */
html body.ag2.no-blur {
    --ag2-mat-side: var(--ag2-solid-side);
    --ag2-mat-float: var(--ag2-solid-float);
    --ag2-mat-window: var(--ag2-solid-window);
    --ag2-mat-menu: var(--ag2-solid-menu);
    --ag2-blur-side: none;
    --ag2-blur-float: none;
    --ag2-blur-window: none;
    --ag2-blur-menu: none;
}

/* == 1 · Typography == */
/* Ported from apple-theme.css §1 (font stack, Font Awesome protection, crisp text),
   re-scoped to body.ag2 and moved onto the AG2 tokens. Reading-area sizes (§5.3)
   come in P1b together with the reading layout. */

html body.ag2,
html body.ag2 input,
html body.ag2 textarea,
html body.ag2 select,
html body.ag2 button:not([class*="fa-"]),
html body.ag2 .menu_button:not([class*="fa-"]),
html body.ag2 .text_pole {
    font-family: var(--ag2-font) !important;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
}

/* The font-family rule above would hit icon elements too: keep Font Awesome on
   every element that renders an FA glyph. */
html body.ag2 .fa,
html body.ag2 .fas,
html body.ag2 .far,
html body.ag2 .fa-solid,
html body.ag2 .fa-regular,
html body.ag2 .fa-classic,
html body.ag2 .menu_button.fa-solid,
html body.ag2 .menu_button.fa-regular,
html body.ag2 .menu_button.fas,
html body.ag2 .right_menu_button.fa-solid,
html body.ag2 .drawer-icon.fa-solid,
html body.ag2 .mes_button.fa-solid,
html body.ag2 .mes_button.fa-regular {
    font-family: "Font Awesome 6 Free", "Font Awesome 5 Free", FontAwesome !important;
}

html body.ag2 .fab,
html body.ag2 .fa-brands,
html body.ag2 .menu_button.fa-brands {
    font-family: "Font Awesome 6 Brands", "Font Awesome 5 Brands" !important;
}

html body.ag2 code,
html body.ag2 pre,
html body.ag2 .mes_text code,
html body.ag2 .monospace {
    font-family: var(--ag2-mono) !important;
}

/* ST themes may set a text shadow; glass surfaces look muddy with it */
html body.ag2 * {
    text-shadow: none !important;
}

html body.ag2 {
    letter-spacing: -0.011em;
    color: var(--ag2-l1);
}

html body.ag2 h1,
html body.ag2 h2,
html body.ag2 h3,
html body.ag2 h4,
html body.ag2 h5 {
    letter-spacing: -0.02em !important;
    font-weight: 600 !important;
    color: var(--ag2-l1);
}

/* Times, token counts and counters line up in columns (§6 "数字") */
html body.ag2 .mes_timer,
html body.ag2 .tokenCounterDisplay,
html body.ag2 .swipes-counter,
html body.ag2 .timestamp {
    font-variant-numeric: tabular-nums;
}

/* == 2 · Layout (§4) == */
/* Both layouts. Phones (≤1000px, body.ag2-phone — width only, §4) re-place #sheld, the
   capsules and the composer in §5.9; the rules here are the shared base. */

html body.ag2 {
    /* #sheld sits between the sidebar and the (optional, P3) inspector */
    --ag2-sheld-left: calc(var(--ag2-inset) * 2 + var(--ag2-side-w));
    --ag2-sheld-right: var(--ag2-inset);
    /* chat fades: top under the capsules; bottom grows to 140px once the composer
       floats over the chat (P1b) */
    --ag2-fade-top: 70px;
    --ag2-fade-bottom: 24px;
}

html body.ag2.ag2-side-collapsed {
    --ag2-sheld-left: var(--ag2-inset);
}

@media screen { /* desktop + phone since P5 */
    /* Old top bar: background strip goes; the icon holder must stay a z-3005
       stacking context (no display:none / transform / filter — §9.2 #1/#2), so its
       toggles are only made invisible and the strip click-through. Drawers inside
       still open through ST's own handler. */
    html body.ag2:not(#_):not(#__) #top-bar {
        display: none !important;
    }

    html body.ag2:not(#_):not(#__) #top-settings-holder {
        pointer-events: none !important;
        background: none !important;
        border: 0 !important;
        box-shadow: none !important;
    }

    html body.ag2:not(#_):not(#__) #top-settings-holder > .drawer > .drawer-toggle {
        visibility: hidden !important;
        pointer-events: none !important;
    }

    html body.ag2:not(#_):not(#__) #top-settings-holder .drawer-content {
        pointer-events: auto !important;
    }

    /* #sheld stays the chat body; only its box moves (§9.2 #8). ST writes
       --sheldWidth inline on :root, hence the !important overrides. */
    html body.ag2:not(#_):not(#__) #sheld {
        position: fixed !important;
        top: 0 !important;
        bottom: 0 !important;
        left: var(--ag2-sheld-left) !important;
        right: var(--ag2-sheld-right) !important;
        width: auto !important;
        max-width: none !important;
        height: 100dvh !important;
        max-height: 100dvh !important;
        margin: 0 !important;
        transition: left var(--ag2-dur-panel) var(--ag2-ease-sheet);
    }

    /* Reading column width is a shell variable (appearance page, P2a). The scroll
       container stays full width so the scrollbar sits at the edge of the chat area;
       the padding centres the column. Top padding clears the capsules. */
    html body.ag2:not(#_):not(#__) #chat {
        padding-top: 72px !important;
        padding-inline: max(var(--ag2-pad), calc((100% - var(--ag2-read-width)) / 2)) !important;
        background: none !important;
        backdrop-filter: none !important;
        -webkit-backdrop-filter: none !important;
        border: 0 !important;
        box-shadow: none !important;
        /* text flows under the glass capsules instead of being cut hard (§4) */
        -webkit-mask-image: linear-gradient(to bottom, transparent 0, #000 var(--ag2-fade-top), #000 calc(100% - var(--ag2-fade-bottom)), transparent 100%);
        mask-image: linear-gradient(to bottom, transparent 0, #000 var(--ag2-fade-top), #000 calc(100% - var(--ag2-fade-bottom)), transparent 100%);
    }

    /* Composer column (the floating input island itself: §5.4) */
    html body.ag2:not(#_):not(#__) #form_sheld {
        width: min(100%, calc(var(--ag2-read-width) + var(--ag2-pad) * 2)) !important;
        max-width: none !important;
        margin-inline: auto !important;
        padding-bottom: var(--ag2-inset);
    }

    /* Welcome: ST's .welcomePanel + system messages in #chat are hidden; the shell
       draws its own page outside #sheld (§5.10). visibility keeps ST's layout and
       scroll maths intact. */
    html body.ag2.ag2-welcome:not(#_):not(#__) #sheld {
        visibility: hidden !important;
    }
}

/* == 2.1 · Shell frame == */
/* #ag2-shell is a child of <body>, outside #sheld. z 40: above #sheld (30) but
   below #top-settings-holder (3005) and ST's legacy popups (§9.2 #2/#10). The frame
   itself is click-through; only its islands take pointer events. */

html body.ag2 #ag2-shell {
    position: fixed;
    inset: 0;
    z-index: var(--ag2-z-capsule);
    pointer-events: none;
    color: var(--ag2-l1);
    font-size: var(--ag2-fs-body);
}

html body.ag2 #ag2-shell > * {
    pointer-events: auto;
}

html body.ag2 :is(#ag2-shell, #ag2-layer) button {
    font: inherit;
    color: inherit;
    margin: 0;
    border: 0;
    background: none;
    cursor: pointer;
    -webkit-appearance: none;
    appearance: none;
    -webkit-tap-highlight-color: transparent;
}

html body.ag2 :is(#ag2-shell, #ag2-layer) :focus {
    outline: none;
}

/* Focus ring only for keyboard use (§8): 3px accent */
html body.ag2 :is(#ag2-shell, #ag2-layer, #ag2-settings) :focus-visible {
    outline: 3px solid var(--ag2-accent) !important;
    outline-offset: 1px;
}

html body.ag2 .ag2-i {
    flex: none;
    display: block;
}

/* Icon button: 32×32 control, no blur (small control, §7) */
html body.ag2 #ag2-shell .ag2-ib {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex: none;
    width: 32px;
    height: 32px;
    padding: 0;
    border-radius: var(--ag2-r-ctl);
    color: var(--ag2-l2);
    transition: background-color var(--ag2-dur) ease, color var(--ag2-dur) ease;
}

html body.ag2 #ag2-shell .ag2-ib:hover {
    background: var(--ag2-f4);
    color: var(--ag2-l1);
}

html body.ag2 #ag2-shell .ag2-ib:active {
    background: var(--ag2-f3);
    transition-duration: var(--ag2-dur-press);
}

/* Pill button (welcome / empty states) */
html body.ag2 #ag2-shell .ag2-btn {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    height: 36px;
    padding: 0 16px;
    border-radius: 18px;
    background: var(--ag2-f2);
    color: var(--ag2-l1);
    font-size: var(--ag2-fs-body);
    font-weight: 590;
    white-space: nowrap;
    transition: background-color var(--ag2-dur) ease;
}

html body.ag2 #ag2-shell .ag2-btn:hover {
    background: var(--ag2-f1);
}

html body.ag2 .ag2-av {
    flex: none;
    display: block;
    border-radius: 50%;
    object-fit: cover;
    background: var(--ag2-f3);
}

html body.ag2 .ag2-av-42 { width: 42px; height: 42px; }
html body.ag2 .ag2-av-36 { width: 36px; height: 36px; }
html body.ag2 .ag2-av-32 { width: 32px; height: 32px; }
html body.ag2 .ag2-av-28 { width: 28px; height: 28px; }

/* Group avatar without a custom image: two member avatars overlapped */
html body.ag2 .ag2-av-stack {
    position: relative;
    background: none;
    color: var(--ag2-l2);
    display: inline-flex;
    align-items: center;
    justify-content: center;
}

html body.ag2 .ag2-av-stack > img {
    position: absolute;
    width: 72%;
    height: 72%;
    border-radius: 50%;
    object-fit: cover;
    box-shadow: 0 0 0 1.5px rgba(30, 30, 36, 0.9);
}

html body.ag2 .ag2-av-stack > img:first-child { left: 0; top: 0; }
html body.ag2 .ag2-av-stack > img:nth-child(2) { right: 0; bottom: 0; }
html body.ag2 .ag2-av-stack > img:only-child { position: static; width: 100%; height: 100%; }

/* == 3 · Sidebar (§5.1) == */

html body.ag2 #ag2-sidebar {
    position: absolute;
    left: var(--ag2-inset);
    top: var(--ag2-inset);
    bottom: var(--ag2-inset);
    width: var(--ag2-side-w);
    display: flex;
    flex-direction: column;
    overflow: hidden;
    border-radius: var(--ag2-r-panel);
    background: var(--ag2-mat-side);
    -webkit-backdrop-filter: var(--ag2-blur-side);
    backdrop-filter: var(--ag2-blur-side);
    box-shadow: var(--ag2-rim), var(--ag2-sh2);
    transition: transform var(--ag2-dur-panel) var(--ag2-ease-sheet), visibility 0s linear 0s;
}

/* Collapsed: slide out, then drop from the a11y tree / tab order */
html body.ag2.ag2-side-collapsed #ag2-sidebar {
    transform: translateX(calc(-100% - var(--ag2-inset) * 2));
    visibility: hidden;
    transition: transform var(--ag2-dur-panel) var(--ag2-ease-sheet), visibility 0s linear var(--ag2-dur-panel);
}

html body.ag2 .ag2-side-head {
    display: flex;
    align-items: center;
    gap: 6px;
    height: 52px;
    flex: none;
    padding: 6px 10px 0 10px;
}

html body.ag2 .ag2-side-title {
    flex: 1;
    min-width: 0;
    font-size: var(--ag2-fs-headline);
    font-weight: 650;
    letter-spacing: -0.01em;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

/* Search opens the ⌘K palette (P4); it is a button, not a second search UI */
html body.ag2 #ag2-shell .ag2-search {
    display: flex;
    align-items: center;
    gap: 8px;
    flex: none;
    height: 34px;
    margin: 4px 12px 10px;
    padding: 0 8px 0 10px;
    border-radius: 10px;
    background: var(--ag2-f3);
    color: var(--ag2-l3);
    font-size: var(--ag2-fs-sub);
    text-align: left;
    transition: background-color var(--ag2-dur) ease;
}

html body.ag2 #ag2-shell .ag2-search:hover {
    background: var(--ag2-f2);
}

html body.ag2 .ag2-search-ph {
    flex: 1;
    min-width: 0;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

html body.ag2 #ag2-shell kbd {
    flex: none;
    padding: 1px 6px;
    border-radius: 5px;
    background: var(--ag2-f4);
    box-shadow: inset 0 0 0 0.5px var(--ag2-sep-strong);
    color: var(--ag2-l3);
    font: 600 11px/16px var(--ag2-font);
}

/* Segmented control: filled track, raised selected segment, no borders */
html body.ag2 .ag2-seg {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 2px;
    flex: none;
    margin: 0 12px 8px;
    padding: 2px;
    border-radius: var(--ag2-r-ctl);
    background: var(--ag2-f3);
}

html body.ag2 #ag2-shell .ag2-seg > button {
    height: 28px;
    border-radius: 7px;
    color: var(--ag2-l2);
    font-size: 13px;
    font-weight: 590;
    white-space: nowrap;
    transition: background-color var(--ag2-dur) ease, color var(--ag2-dur) ease;
}

html body.ag2 #ag2-shell .ag2-seg > button.ag2-on {
    background: rgba(255, 255, 255, 0.15);
    color: var(--ag2-l1);
    box-shadow: 0 1px 2px rgba(0, 0, 0, 0.25), inset 0 0.5px 0 rgba(255, 255, 255, 0.12);
}

html body.ag2 .ag2-side-list {
    flex: 1;
    min-height: 0;
    overflow-x: hidden;
    overflow-y: auto;
    overscroll-behavior: contain;
    padding: 0 6px 8px;
    scrollbar-width: thin;
    scrollbar-color: var(--ag2-f2) transparent;
}

/* Group header (置顶 / 最近 / 更早): 11.5/620, quaternary-ish grey */
html body.ag2 .ag2-sec {
    padding: 12px 10px 4px;
    color: var(--ag2-l3);
    font-size: var(--ag2-fs-section);
    font-weight: 620;
}

html body.ag2 #ag2-shell .ag2-row {
    display: flex;
    align-items: center;
    gap: 11px;
    width: 100%;
    min-width: 0;
    padding: 8px 10px;
    border-radius: var(--ag2-r-row);
    text-align: left;
    cursor: pointer;
    user-select: none;
    -webkit-user-select: none;
    transition: background-color var(--ag2-dur) ease;
}

html body.ag2 #ag2-shell .ag2-row:hover {
    background: rgba(255, 255, 255, 0.06);
}

/* Selected: .11 fill + top inner highlight (§5.1) */
html body.ag2 #ag2-shell .ag2-row.ag2-on {
    background: rgba(255, 255, 255, 0.11);
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08);
}

html body.ag2 .ag2-row-body {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 2px;
}

html body.ag2 .ag2-row-top {
    display: flex;
    align-items: baseline;
    gap: 8px;
    min-width: 0;
}

html body.ag2 .ag2-row-name {
    flex: 1;
    min-width: 0;
    font-size: 14px;
    font-weight: 600;
    line-height: 19px;
    color: var(--ag2-l1);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

html body.ag2 .ag2-row-time {
    flex: none;
    display: inline-flex;
    align-items: center;
    gap: 4px;
    color: var(--ag2-l3);
    font-size: 11.5px;
    font-variant-numeric: tabular-nums;
}

html body.ag2 .ag2-row-time .ag2-pin,
html body.ag2 .ag2-row-time .ag2-fav {
    color: var(--ag2-l3);
}

html body.ag2 .ag2-row-sub {
    display: block;
    min-width: 0;
    color: var(--ag2-l2);
    font-size: var(--ag2-fs-foot);
    line-height: 17px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

html body.ag2 .ag2-row-prefix {
    color: var(--ag2-l3);
}

html body.ag2 .ag2-empty,
html body.ag2 .ag2-empty-note {
    padding: 28px 16px;
    color: var(--ag2-l3);
    font-size: var(--ag2-fs-sub);
    text-align: center;
}

html body.ag2 .ag2-empty {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 12px;
}

html body.ag2 .ag2-empty-title {
    color: var(--ag2-l2);
    font-size: var(--ag2-fs-headline);
    font-weight: 600;
}

html body.ag2 .ag2-empty-actions {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 8px;
}

/* Footer: hairline above, inset to the content edge (§2.4) */
html body.ag2 .ag2-side-foot {
    flex: none;
    position: relative;
    padding: 8px 10px 10px;
}

html body.ag2 .ag2-side-foot::before {
    content: "";
    position: absolute;
    top: 0;
    left: 14px;
    right: 14px;
    height: 0.5px;
    background: var(--ag2-sep-strong);
}

html body.ag2 #ag2-shell .ag2-conn {
    display: flex;
    align-items: center;
    gap: 8px;
    width: 100%;
    height: 30px;
    padding: 0 8px;
    border-radius: var(--ag2-r-ctl);
    color: var(--ag2-l2);
    font-size: var(--ag2-fs-foot);
    text-align: left;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

html body.ag2 #ag2-shell .ag2-conn:hover,
html body.ag2 #ag2-shell .ag2-persona:hover {
    background: var(--ag2-f4);
}

html body.ag2 .ag2-dot {
    flex: none;
    width: 7px;
    height: 7px;
    border-radius: 50%;
    background: var(--ag2-red);
}

html body.ag2 .ag2-conn.ag2-ok .ag2-dot {
    background: var(--ag2-green);
    box-shadow: 0 0 6px rgba(48, 209, 88, 0.55);
}

html body.ag2 .ag2-conn-text {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
}

html body.ag2 .ag2-foot-row {
    display: flex;
    align-items: center;
    gap: 4px;
    margin-top: 4px;
}

html body.ag2 #ag2-shell .ag2-persona {
    flex: 1;
    min-width: 0;
    display: flex;
    align-items: center;
    gap: 10px;
    height: 40px;
    padding: 0 6px;
    border-radius: var(--ag2-r-row);
    text-align: left;
}

html body.ag2 .ag2-persona-name {
    min-width: 0;
    font-size: var(--ag2-fs-sub);
    font-weight: 600;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

html body.ag2 .ag2-persona-sub {
    flex: none;
    color: var(--ag2-l3);
    font-size: 11.5px;
}

/* == 4 · Capsules (§5.2) == */

html body.ag2 #ag2-shell .ag2-cap {
    position: absolute;
    top: var(--ag2-inset);
    height: 44px;
    display: flex;
    align-items: center;
    border-radius: 22px;
    background: var(--ag2-mat-float);
    -webkit-backdrop-filter: var(--ag2-blur-float);
    backdrop-filter: var(--ag2-blur-float);
    box-shadow: var(--ag2-rim), var(--ag2-sh2);
    transition: left var(--ag2-dur-panel) var(--ag2-ease-sheet), right var(--ag2-dur-panel) var(--ag2-ease-sheet);
}

html body.ag2 #ag2-title {
    left: calc(var(--ag2-sheld-left) + var(--ag2-inset));
    max-width: calc(100vw - var(--ag2-sheld-left) - var(--ag2-sheld-right) - var(--ag2-tools-w, 232px) - 30px);
    padding: 0 10px 0 6px;
    gap: 2px;
}

html body.ag2 #ag2-shell .ag2-expand {
    display: none;
}

html body.ag2.ag2-side-collapsed #ag2-shell .ag2-expand {
    display: inline-flex;
}

html body.ag2 #ag2-shell .ag2-title-btn {
    display: flex;
    align-items: center;
    gap: 9px;
    min-width: 0;
    height: 44px;
    padding: 0 2px;
    text-align: left;
    cursor: pointer;
    user-select: none;
    -webkit-user-select: none;
    border-radius: 18px;
}

html body.ag2 .ag2-title-av {
    flex: none;
    width: 32px;
    height: 32px;
    border-radius: 50%;
    overflow: hidden;
}

html body.ag2 .ag2-title-av.ag2-av-stack {
    overflow: visible;
}

html body.ag2 .ag2-title-av > img {
    display: block;
    width: 100%;
    height: 100%;
    border-radius: 50%;
    object-fit: cover;
}

html body.ag2 .ag2-title-av.ag2-av-stack > img {
    width: 72%;
    height: 72%;
}

html body.ag2 .ag2-title-text {
    display: flex;
    flex-direction: column;
    min-width: 0;
}

html body.ag2 .ag2-title-name {
    font-size: 14px;
    font-weight: 640;
    line-height: 18px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

html body.ag2 .ag2-title-sub {
    color: var(--ag2-l2);
    font-size: 11.5px;
    line-height: 15px;
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

html body.ag2 .ag2-chev {
    color: var(--ag2-l3);
}

html body.ag2 #ag2-tools {
    right: calc(var(--ag2-sheld-right) + var(--ag2-inset));
    padding: 0 6px;
    gap: 2px;
    /* Leave a readable title at narrow desktop widths, even with long translations.
       chrome.js measures this constrained capsule rather than guessing a label width. */
    max-width: max(128px, calc(100vw - var(--ag2-sheld-left) - var(--ag2-sheld-right) - var(--ag2-insp-cover, 0px) - 180px));
}

html body.ag2 #ag2-shell .ag2-tool { min-width: 0; }
html body.ag2 #ag2-shell .ag2-tool > span { min-width: 0; overflow: hidden; text-overflow: ellipsis; }
html body.ag2 #ag2-shell .ag2-tool > svg,
html body.ag2 #ag2-tools > :is(.ag2-cap-sep, .ag2-insp-toggle) { flex-shrink: 0; }

html body.ag2 #ag2-shell .ag2-tool {
    position: relative;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    height: 32px;
    padding: 0 10px;
    border-radius: 16px;
    color: var(--ag2-l1);
    font-size: 13px;
    white-space: nowrap;
    transition: background-color var(--ag2-dur) ease;
}

html body.ag2 #ag2-shell .ag2-tool:hover {
