}

html body.ag2 #ag2-shell .ag2-tool.ag2-on {
    background: var(--ag2-accent-soft);
    color: var(--ag2-accent-hover);
}

html body.ag2 #ag2-shell .ag2-tool .ag2-i {
    color: var(--ag2-l2);
}

html body.ag2 #ag2-shell .ag2-tool.ag2-on .ag2-i {
    color: var(--ag2-accent-hover);
}

/* Small dot: chat has a bound lorebook / non-empty author's note (§5.2) */
html body.ag2 .ag2-badge {
    display: none;
    position: absolute;
    top: 5px;
    left: 20px;
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: var(--ag2-accent);
}

html body.ag2 .ag2-tool.ag2-has .ag2-badge {
    display: block;
}

html body.ag2 .ag2-cap-sep {
    width: 0.5px;
    height: 18px;
    margin: 0 4px;
    background: var(--ag2-sep-strong);
}

/* No chat open: the welcome page owns the stage; the title capsule only keeps
   its expand button when the sidebar is collapsed. */
html body.ag2.ag2-welcome #ag2-tools,
html body.ag2.ag2-welcome:not(.ag2-side-collapsed) #ag2-title,
html body.ag2.ag2-welcome #ag2-title .ag2-title-btn {
    display: none;
}

html body.ag2.ag2-welcome #ag2-title {
    padding: 0 6px;
}

/* == 5.8 · Menus (popover) == */

html body.ag2 :is(#ag2-shell, #ag2-layer) .ag2-menu {
    position: fixed;
    z-index: 1;
    display: flex;
    flex-direction: column;
    min-width: 208px;
    max-width: 320px;
    padding: 5px;
    border-radius: 14px;
    background: var(--ag2-mat-menu);
    -webkit-backdrop-filter: var(--ag2-blur-menu);
    backdrop-filter: var(--ag2-blur-menu);
    box-shadow: var(--ag2-rim), var(--ag2-sh3);
    animation: ag2-pop var(--ag2-dur) var(--ag2-ease);
}

@keyframes ag2-pop {
    from { opacity: 0; transform: scale(0.97); }
    to { opacity: 1; transform: none; }
}

html body.ag2 :is(#ag2-shell, #ag2-layer) .ag2-menu-item {
    display: flex;
    align-items: center;
    gap: 10px;
    width: 100%;
    height: 32px;
    padding: 0 10px;
    border-radius: 9px;
    color: var(--ag2-l1);
    font-size: var(--ag2-fs-sub);
    text-align: left;
    white-space: nowrap;
}

html body.ag2 :is(#ag2-shell, #ag2-layer) .ag2-menu-item .ag2-i {
    color: var(--ag2-l2);
}

html body.ag2 :is(#ag2-shell, #ag2-layer) .ag2-menu-item:hover:not(:disabled),
html body.ag2 :is(#ag2-shell, #ag2-layer) .ag2-menu-item:focus-visible {
