    outline: none !important;
}

html body.ag2 :is(#ag2-shell, #ag2-layer) .ag2-menu-item:hover:not(:disabled) .ag2-i,
html body.ag2 :is(#ag2-shell, #ag2-layer) .ag2-menu-item:focus-visible .ag2-i {
    color: #fff;
}

html body.ag2 :is(#ag2-shell, #ag2-layer) .ag2-menu-item.ag2-danger,
html body.ag2 :is(#ag2-shell, #ag2-layer) .ag2-menu-item.ag2-danger .ag2-i {
    color: var(--ag2-red);
}

html body.ag2 :is(#ag2-shell, #ag2-layer) .ag2-menu-item.ag2-danger:hover,
html body.ag2 :is(#ag2-shell, #ag2-layer) .ag2-menu-item.ag2-danger:focus-visible {
    background: var(--ag2-red);
}

html body.ag2 :is(#ag2-shell, #ag2-layer) .ag2-menu-item.ag2-danger:hover .ag2-i,
html body.ag2 :is(#ag2-shell, #ag2-layer) .ag2-menu-item.ag2-danger:focus-visible .ag2-i {
    color: #fff;
}

html body.ag2 :is(#ag2-shell, #ag2-layer) .ag2-menu-item:disabled {
    color: var(--ag2-l4);
    cursor: default;
}

html body.ag2 :is(#ag2-shell, #ag2-layer) .ag2-menu-item:disabled .ag2-i {
    color: var(--ag2-l4);
}

html body.ag2 .ag2-menu-label {
    flex: 1;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
}

html body.ag2 .ag2-menu-hint {
    color: var(--ag2-l3);
    font-size: 12px;
}

html body.ag2 .ag2-i-pad {
    flex: none;
    width: 16px;
}

html body.ag2 .ag2-menu-sep {
    height: 0.5px;
    margin: 5px 10px;
    background: var(--ag2-sep-strong);
}

html body.ag2 .ag2-menu-head {
    padding: 6px 10px 2px;
    color: var(--ag2-l3);
    font-size: var(--ag2-fs-section);
    font-weight: 620;
}

/* == 5.10 · Welcome page (no chat open) == */

html body.ag2 #ag2-welcome {
    position: absolute;
    top: 0;
    bottom: 0;
    left: var(--ag2-sheld-left);
    right: var(--ag2-sheld-right);
    display: none;
    overflow-x: hidden;
    overflow-y: auto;
    transition: left var(--ag2-dur-panel) var(--ag2-ease-sheet);
}

html body.ag2.ag2-welcome #ag2-welcome {
    display: flex;
    align-items: center;
    justify-content: center;
    /* soft scrim (no blur) so the greeting stays legible on bright backgrounds */
    background: radial-gradient(ellipse 70% 60% at 50% 50%, rgba(0, 0, 0, 0.42), rgba(0, 0, 0, 0.12) 70%, transparent 100%);
}

/* Welcome actions sit on the wallpaper: tinted like the cards */
html body.ag2 #ag2-shell .ag2-wel-actions .ag2-btn {
    background: rgba(30, 30, 36, 0.72);
    box-shadow: var(--ag2-rim);
}

html body.ag2 #ag2-shell .ag2-wel-actions .ag2-btn:hover {
    background: rgba(44, 44, 51, 0.86);
}

html body.ag2 .ag2-wel-inner {
    width: min(760px, calc(100% - var(--ag2-pad-wide) * 2));
    margin: auto 0;
    padding: 48px 0;
}

html body.ag2 .ag2-wel-title {
    margin: 0 0 6px !important;
    color: var(--ag2-l1);
    font-size: 30px !important;
    font-weight: 720 !important;
    line-height: 1.2;
}

html body.ag2 .ag2-wel-sub {
    margin: 0 0 24px;
    color: var(--ag2-l2);
    font-size: var(--ag2-fs-headline);
}

html body.ag2 .ag2-wel-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 12px;
}

/* Cards are small surfaces: tinted fill + rim, no blur (§7 budget) */
html body.ag2 #ag2-shell .ag2-wel-card {
    display: flex;
    flex-direction: column;
    gap: 10px;
    min-width: 0;
    padding: 14px;
    border-radius: var(--ag2-r-card);
    background: rgba(30, 30, 36, 0.72);
    box-shadow: var(--ag2-rim), var(--ag2-sh1);
    text-align: left;
    cursor: pointer;
    user-select: none;
    -webkit-user-select: none;
    transition: background-color var(--ag2-dur) ease;
}

html body.ag2 #ag2-shell .ag2-wel-card:hover {
    background: rgba(44, 44, 51, 0.82);
}

html body.ag2 .ag2-wel-card-head {
    display: flex;
    align-items: center;
    gap: 10px;
    min-width: 0;
}

html body.ag2 .ag2-wel-card-text {
    display: -webkit-box;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
    line-clamp: 2;
    overflow: hidden;
    color: var(--ag2-l2);
    font-size: 13px;
    line-height: 19px;
    min-height: 38px;
}

html body.ag2 .ag2-wel-actions {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    margin-top: 22px;
}

/* == 5.3a · Jump-to-latest pill (ported from apple-theme.css §17g) == */
/* The pill is created by the extension's index.js (feature 3) under both Apple Glass
   themes; without these rules it would render as a bare button above the composer. */

html body.ag2:not(#_):not(#__) #form_sheld {
    position: relative;
}

html body.ag2:not(#_):not(#__) #ap-jump-latest {
    display: inline-flex;
    position: absolute;
    left: 50%;
    bottom: calc(100% + 10px);
    z-index: 30;
    align-items: center;
    gap: 6px;
    height: 32px;
    padding: 0 14px 0 12px;
    border: 0;
    border-radius: var(--ag2-r-full);
    background: rgba(44, 44, 50, 0.92);  /* opaque-ish: small control, no blur (§7) */
    color: var(--ag2-l1);
    font: 500 12.5px/1 var(--ag2-font);
    letter-spacing: -0.01em;
    box-shadow: var(--ag2-rim), var(--ag2-sh2);
    cursor: pointer;
    opacity: 0;
    pointer-events: none;
    transform: translateX(-50%) translateY(6px);
    transition: opacity var(--ag2-dur) var(--ag2-ease), transform var(--ag2-dur) var(--ag2-ease);
}

html body.ag2:not(#_):not(#__) #ap-jump-latest.is-visible {
    opacity: 1;
    pointer-events: auto;
    transform: translateX(-50%) translateY(0);
}

html body.ag2:not(#_):not(#__) #ap-jump-latest:active {
    transform: translateX(-50%) scale(0.96);
}

html body.ag2:not(#_):not(#__) #ap-jump-latest i {
    font-size: 11px;
    opacity: 0.8;
}

html body.ag2.immersive-mode:not(#_):not(#__) #ap-jump-latest {
    display: none !important;
}

/* == 5.3 · Reading area (§5.3) == */
/* Both layouts since P5 (§5.9 adjusts gutters on phones).
   Every message keeps ST's DOM. The layout is a CSS grid on .mes: the wrappers
   .mesAvatarWrapper / .mes_block / .ch_name / .swipeRightBlock become display:contents,
   so their children (avatar, name line, reasoning, text, buttons, swipe chevrons and
   counter, timer, token count) are placed straight into named grid areas. Nothing is
   moved or inserted (§9.2 #7/#8); 小白X still finds .mes_block > .ch_name and
   .mes_buttons. Pseudo-elements carry the extra visuals:
     .mes::before                 day separator (data-ag2-day, set by shell/reading.js)
     .mes::after                  model name in the meta line (data-ag2-model)
     .mes_block::before           card surface of the card styles (z -1, behind the text)
     .mes_block::after            portrait backdrop (echo / whisper)
     .swipeRightBlock::before     ‹ 2/3 › capsule background
   Columns: outer | card pad | ‹ | count | › | buttons | 1fr | model | tokens | time | pad
   Rows:    day | top pad | head | reasoning | text | media | file | bias | actions | bottom pad
   The chat styles (§5.3b) only change the pad variables, the card and the portrait. */

@media screen { /* desktop + phone since P5 (§5.9 overrides the geometry) */
    html body.ag2:not(#_):not(#__) {
        /* the composer floats over the chat from P1b on (§4: bottom fade 140px) */
        --ag2-fade-bottom: 140px;
    }

    /* Wallpaper scrim (design 01 “wall”): long prose sits directly on the wallpaper
       now (no bubble), so the background is darkened towards the bottom. */
    html body.ag2:not(#_):not(#__) #bg1::after {
        content: "";
        position: absolute;
        inset: 0;
        background: linear-gradient(180deg, rgba(9, 9, 13, 0.52), rgba(9, 9, 13, 0.70) 55%, rgba(9, 9, 13, 0.82));
        pointer-events: none;
    }

    html body.ag2:not(#_):not(#__) #chat {
        /* the island floats over the chat: pad by its live height (composer.js) */
        padding-bottom: calc(var(--ag2-dock-h, 112px) + 18px) !important;
        max-height: none !important;
        text-shadow: none !important;
    }

    html body.ag2:not(#_):not(#__) #chat .mes {
        --ag2-mes-ol: 0px;      /* outer column (ripple portrait) */
        --ag2-mes-pl: 0px;      /* card inner padding: left / right / top / bottom */
        --ag2-mes-pr: 0px;
        --ag2-mes-pt: 0px;
        --ag2-mes-pb: 0px;
        grid-template-columns:
            [outer] var(--ag2-mes-ol) [card] var(--ag2-mes-pl)
            [in sw] auto [cnt] auto [swr] auto [btns] auto [gap] minmax(0, 1fr)
            [model] auto [tok] auto [tim] auto [pr] var(--ag2-mes-pr) [end];
        grid-template-rows:
            [day] auto [top] var(--ag2-mes-pt) [head] auto [reason] auto [text] auto
            [media] auto [file] auto [bias] auto [acts] auto [bottom] var(--ag2-mes-pb) [end];
        align-items: start;
        width: 100% !important;
        padding: 0 !important;
        margin: 0 0 18px !important;
        background: none !important;
        border: 0 !important;
        box-shadow: none !important;
        color: var(--ag2-l1);
    }

    /* ST hides some messages with .displayNone (tool calls): keep that */
    html body.ag2:not(#_):not(#__) #chat .mes:not(.displayNone) {
        display: grid !important;
    }

    /* unknown (third-party) children get the content column; rows: auto placement
       after the occupied ones, i.e. under the message. :where() keeps these at the
       lowest specificity so every named placement below wins. */
    html body.ag2:not(#_):not(#__) #chat .mes > :where(*),
    html body.ag2:not(#_):not(#__) #chat .mes > :where(.mes_block) > :where(*),
    html body.ag2:not(#_):not(#__) #chat .mes > :where(.mes_block) > :where(.ch_name) > :where(*) {
        grid-column: in / pr;
        min-width: 0;
    }

    html body.ag2:not(#_):not(#__) #chat .mes:not(.smallSysMes) > .mesAvatarWrapper,
    html body.ag2:not(#_):not(#__) #chat .mes > .mes_block,
    html body.ag2:not(#_):not(#__) #chat .mes > .mes_block > .ch_name,
    html body.ag2:not(#_):not(#__) #chat .mes > .swipeRightBlock {
        display: contents !important;
    }

    html body.ag2:not(#_):not(#__) #chat .mes > .for_checkbox,
    html body.ag2:not(#_):not(#__) #chat .mes .mesIDDisplay {
        display: none !important;
    }

    html body.ag2:not(#_):not(#__) #chat .mes > .del_checkbox {
        grid-row: head;
        grid-column: in / pr;
        justify-self: end;
        margin: 4px 0 0;
    }

    /* Day separator: centred small date above the first message of a day (§5.3).
       Generated for every message (empty unless a new day) so the row is always taken
       and third-party children are never auto-placed above the message. */
    html body.ag2:not(#_):not(#__) #chat .mes::before {
        content: "";
        grid-row: day;
        grid-column: outer / end;
        display: block;
    }

    html body.ag2:not(#_):not(#__) #chat .mes.ag2-day::before {
        content: attr(data-ag2-day);
        margin: 6px 0 22px;
        text-align: center;
        color: var(--ag2-l3);
        font-size: var(--ag2-fs-section);
        font-weight: 560;
        letter-spacing: 0.02em;
        font-variant-numeric: tabular-nums;
    }

    /* Card surface (card styles paint it; spans the message box, behind the text —
       #chat is the stacking context, it has no background). Always generated so the
       card rows are occupied (see above). */
    html body.ag2:not(#_):not(#__) #chat .mes > .mes_block::before {
        content: "";
        grid-row: top / end;
        grid-column: card / end;
        align-self: stretch;
        z-index: -1;
        pointer-events: none;
    }

    /* --- head: avatar 28 · name 13.5/640 · time 11.5 --- */
