        padding: 0 !important;
        background: none;
        box-shadow: none;
    }

    html body.ag2:not(#_):not(#__) #chat .mes[is_user="true"] :is(.mes_buttons, .mes_edit_buttons) {
        grid-column: in / pr;
        justify-self: end;
    }

    /* edit-mode buttons: ST's menu_button glyphs as compact filled buttons */
    html body.ag2:not(#_):not(#__) #chat .mes .mes_edit_buttons > .menu_button {
        align-items: center;
        justify-content: center;
        width: 30px !important;
        height: 30px !important;
        min-width: 30px;
        margin: 0 !important;
        padding: 0 !important;
        border: 0 !important;
        border-radius: 8px !important;
        background: var(--ag2-f4) !important;
        box-shadow: none !important;
        color: var(--ag2-l2) !important;
        font-size: 13px !important;
    }

    html body.ag2:not(#_):not(#__) #chat .mes .mes_edit_buttons > .menu_button:hover {
        background: var(--ag2-f2) !important;
        color: var(--ag2-l1) !important;
    }

    html body.ag2:not(#_):not(#__) #chat .mes[is_system="true"] .mes_text {
        color: var(--ag2-l2) !important;
    }

    html body.ag2.hideChatAvatars:not(#_):not(#__) #chat .mes .ch_name > :first-child {
        padding-left: 0;
    }
}

/* == 5.3b · Chat styles (bubble · document · echo · whisper · ripple · hush) == */
/* chat_display 0 (no body class) is the reading style above. The other six only set
   the card padding variables and paint the card / portrait pseudo-elements, so the
   grid, the action row and the swipe capsule behave the same in all seven. User
   messages keep the grey bubble (document style excepted). Portraits come from
   --ap-mes-avatar, set per message by the extension's index.js (feature 1). */

@media screen { /* desktop + phone since P5 (§5.9 overrides the geometry) */
    /* shared card: one solid surface per AI message (no blur on messages, §5.10) */
    html body.ag2:is(.bubblechat, .ap-chat-echo, .ap-chat-whisper, .ap-chat-ripple, .ap-chat-hush):not(#_):not(#__) #chat .mes:not([is_user="true"]) {
        --ag2-mes-pl: 18px;
        --ag2-mes-pr: 18px;
        --ag2-mes-pt: 14px;
        --ag2-mes-pb: 8px;
        margin-bottom: 14px !important;
    }

    html body.ag2:is(.bubblechat, .ap-chat-echo, .ap-chat-whisper, .ap-chat-ripple, .ap-chat-hush):not(#_):not(#__) #chat .mes:not([is_user="true"]) > .mes_block::before {
        border-radius: 20px;
        background: rgba(40, 40, 47, 0.62);
        box-shadow: var(--ag2-rim);
    }

    /* consecutive cards stay separate cards (only the name line goes) */
    html body.ag2:is(.bubblechat, .ap-chat-echo, .ap-chat-whisper, .ap-chat-ripple, .ap-chat-hush):not(#_):not(#__) #chat .mes:has(+ .mes.ag2-cont) {
        margin-bottom: 10px !important;
    }

    /* 1 · 气泡 Bubble: avatar + name inside the card; the user bubble takes the accent */
    html body.ag2.bubblechat:not(#_):not(#__) #chat .mes[is_user="true"] .mes_text {
        background: color-mix(in srgb, var(--ag2-accent) 34%, rgba(40, 40, 47, 0.8));
    }

    /* 2 · 文档 Document: no avatars, no bubbles; speakers marked by name + a hairline */
    html body.ag2.documentstyle:not(#_):not(#__) #chat .mes .mesAvatarWrapper > .avatar {
        display: none !important;
    }

    html body.ag2.documentstyle:not(#_):not(#__) #chat .mes .ch_name > :first-child {
        padding-left: 0;
    }

    html body.ag2.documentstyle:not(#_):not(#__) #chat .mes[is_user="true"]:not(.ag2-cont) .ch_name > :first-child {
        display: flex !important;
    }

    html body.ag2.documentstyle:not(#_):not(#__) #chat .mes[is_user="true"] .mes_text {
        justify-self: stretch;
        max-width: none;
        padding: 0 0 0 14px !important;
        border-radius: 0;
        background: none;
        box-shadow: inset 2px 0 0 var(--ag2-accent);
        color: var(--ag2-l2) !important;
        font-size: var(--ag2-read-size) !important;
        line-height: var(--ag2-read-lh) !important;
    }

    html body.ag2.documentstyle:not(#_):not(#__) #chat .mes[is_user="true"] :is(.mes_buttons, .mes_edit_buttons) {
        justify-self: start;
    }

    html body.ag2.documentstyle:not(#_):not(#__) #chat .mes:not(.ag2-cont):not(.ag2-day) {
        --ag2-mes-pt: 16px;
    }

    html body.ag2.documentstyle:not(#_):not(#__) #chat .mes:not(.ag2-cont):not(.ag2-day) > .mes_block::before {
        border-top: 0.5px solid var(--ag2-sep);
    }

    /* 3 · 回声 Echo: a large portrait column fading into the card's right edge */
    html body.ag2.ap-chat-echo:not(#_):not(#__) #chat .mes:not([is_user="true"]) {
        --ag2-mes-pr: calc(min(20%, 170px) + 14px);
    }

    /* minimum card heights come from the text row: a spanning portrait with a fixed
       height would spread its extra height over every auto row of the grid */
    html body.ag2.ap-chat-echo:not(#_):not(#__) #chat .mes:not([is_user="true"]) .mes_text {
        min-height: 100px;
    }

    html body.ag2.ap-chat-whisper:not(#_):not(#__) #chat .mes:not([is_user="true"]) .mes_text {
        min-height: 48px;
    }

    html body.ag2.ap-chat-ripple:not(#_):not(#__) #chat .mes:not([is_user="true"]):not(.ag2-cont) .mes_text {
        min-height: 64px;
    }

    html body.ag2:is(.ap-chat-echo, .ap-chat-whisper, .ap-chat-hush):not(#_):not(#__) #chat .mes .mesAvatarWrapper > .avatar {
        display: none !important;
    }

    html body.ag2:is(.ap-chat-echo, .ap-chat-whisper, .ap-chat-hush):not(#_):not(#__) #chat .mes .ch_name > :first-child {
        padding-left: 0;
    }

    html body.ag2.ap-chat-echo:not(#_):not(#__) #chat .mes:not([is_user="true"]) > .mes_block::after {
        content: "";
        grid-row: top / end;
        grid-column: pr / end;
        /* absolutely positioned in its grid area: never sizes the tracks */
        position: absolute;
        inset: 0;
        border-radius: 0 20px 20px 0;
        background: var(--ap-mes-avatar) center top / cover no-repeat;
        -webkit-mask-image: linear-gradient(to left, #000 45%, transparent 100%);
        mask-image: linear-gradient(to left, #000 45%, transparent 100%);
        opacity: 0.72;
        z-index: -1;
        pointer-events: none;
    }

    /* 4 · 低语 Whisper: the portrait dissolves into the card's top-right corner,
       an accent tick on the outer edge */
    html body.ag2.ap-chat-whisper:not(#_):not(#__) #chat .mes:not([is_user="true"]) > .mes_block::after {
        content: "";
        grid-row: top / end;
        grid-column: gap / end;
        position: absolute;
        top: 0;
        right: 0;
        width: min(46%, 340px);
        height: 132px;
        border-top-right-radius: 20px;
        background: var(--ap-mes-avatar) center 22% / cover no-repeat;
        -webkit-mask-image: linear-gradient(to left, #000 35%, transparent 100%), linear-gradient(to bottom, #000 45%, transparent 100%);
        -webkit-mask-composite: source-in;
        mask-image: linear-gradient(to left, #000 35%, transparent 100%), linear-gradient(to bottom, #000 45%, transparent 100%);
        mask-composite: intersect;
        opacity: 0.55;
        z-index: -1;
        pointer-events: none;
    }

    html body.ag2.ap-chat-whisper:not(#_):not(#__) #chat .mes:not([is_user="true"]) > .mes_block::before {
        background: linear-gradient(var(--ag2-l2), var(--ag2-l2)) right 0 top 54px / 3px 26px no-repeat, rgba(40, 40, 47, 0.62);
    }

    /* 5 · 涟漪 Ripple: a tall portrait card left of the message, sticky while reading */
    html body.ag2.ap-chat-ripple:not(#_):not(#__) #chat .mes:not([is_user="true"]) {
        --ag2-mes-ol: 108px;
    }

    html body.ag2.ap-chat-ripple:not(#_):not(#__) #chat .mes:not([is_user="true"]):not(.ag2-cont) .mesAvatarWrapper > .avatar {
        grid-row: top / end;
        grid-column: outer / card;
        position: sticky;
        top: 76px;
        width: 96px !important;
        height: 144px !important;
        margin: 0 !important;
        border-radius: 20px !important;
    }

    html body.ag2.ap-chat-ripple:not(#_):not(#__) #chat .mes .mesAvatarWrapper > .avatar img {
        border-radius: 20px !important;
    }

    html body.ag2.ap-chat-ripple:not(#_):not(#__) #chat .mes:not([is_user="true"]) .ch_name > :first-child {
        padding-left: 0;
    }

    /* 6 · 轻声 Hush: avatar-free cards with a quiet edge accent */
    html body.ag2.ap-chat-hush:not(#_):not(#__) #chat .mes:not([is_user="true"]) {
        --ag2-mes-pl: 22px;
        --ag2-mes-pt: 16px;
    }

    html body.ag2.ap-chat-hush:not(#_):not(#__) #chat .mes:not([is_user="true"]) > .mes_block::before {
        background: linear-gradient(var(--ag2-l3), var(--ag2-l3)) left 0 top 18px / 3px calc(100% - 36px) no-repeat, rgba(40, 40, 47, 0.5);
    }

    html body.ag2.ap-chat-hush:not(#_):not(#__) #chat .mes[is_user="true"] .mes_text {
        box-shadow: inset -3px 0 0 var(--ag2-accent), inset 0 0.5px 0 rgba(255, 255, 255, 0.09);
    }
}

/* == 5.3c · Small system messages (§5.3, R3a) == */
/* /sendas … compact=true (e.g. the “Ny规则定下的走向” storyline receipt a preset sends after
   the user picks an option), /sys compact=true, /comment compact=true and ST's own notes all
   render as .mes.smallSysMes (script.js: extra.isSmallSys). ST's native look centres them and
   hides .ch_name + the avatar; the §5.3 grid turns .ch_name back on (display: contents
   !important) while its avatar rule skips .smallSysMes, so they leaked as a headless
   “name line + body” message. Here they are a centred receipt capsule:
       [icon]  caption = the message's own name      (.ch_name > :first-child)
               text                                   (.mes_text)
   Structure: .mes keeps the §5.3 grid (day separator, delete checkbox); .mes_block stops
   being display:contents and IS the capsule (a nested 2-column grid); its ::before is the
   icon. The action row floats under the capsule on hover / tap, so it takes no room.
   Generic: any .smallSysMes, never matched on the text. Only the icon follows ST's own
   attributes: [type="comment"] note · [type="narrator"] quote · [is_system="true"] info ·
   everything else (a /sendas receipt) git-branch. Nothing is moved or inserted.
   Three :not() ids: these must beat the §5.3 / §5.3b / §5.9 message rules (two ids) wherever
   they sit in the file. The default look is the timeline divider layered below (variant C,
   chosen by the user); variant B: tools/ag2/r3a-variants/B.css (handoff/R3a.md). */

@media screen { /* desktop + phone */
    /* no card padding / portrait column: the capsule centres in the whole reading column */
    html body.ag2:not(#_):not(#__):not(#___) #chat .mes.smallSysMes {
        --ag2-mes-ol: 0px;
        --ag2-mes-pl: 0px;
        --ag2-mes-pr: 0px;
        --ag2-mes-pt: 0px;
        --ag2-mes-pb: 0px;
        margin-bottom: 18px !important;
    }

    /* two receipts in a row (same sender → ag2-cont): a small gap, both keep their caption */
    html body.ag2:not(#_):not(#__):not(#___) #chat .mes:has(+ .mes.smallSysMes.ag2-cont) {
        margin-bottom: 8px !important;
    }

    html body.ag2:not(#_):not(#__):not(#___) #chat .mes.smallSysMes > .mes_block {
        display: grid !important;
        grid-row: text;
        grid-column: in / pr;
        justify-self: center;
        position: relative;
        grid-template-columns: auto minmax(0, 1fr);
        grid-auto-rows: auto;
        column-gap: 10px;
        align-items: start;
        box-sizing: border-box;
        width: fit-content;
        max-width: min(100%, 560px);
        min-width: 0;
        margin: 0 !important;
        padding: 9px 16px 10px 13px !important;
        border-radius: var(--ag2-r-card);
        background: var(--ag2-mat-float); /* solid in no-blur mode; no backdrop-filter on messages */
        box-shadow: var(--ag2-rim);
        /* ST: .mes_block { overflow-x: hidden; overflow-y: clip } — as a real box that clips the
           floating action row and turns the capsule into a scroll container (opening “更多”
           scrolled the caption out of it) */
        overflow: visible !important;
    }

    /* every child goes to the content column, rows by document order
       (the §5.3 named lines do not exist in this nested grid) */
    html body.ag2:not(#_):not(#__):not(#___) #chat .mes.smallSysMes > .mes_block > *,
    html body.ag2:not(#_):not(#__):not(#___) #chat .mes.smallSysMes > .mes_block > .ch_name > * {
        grid-column: 2;
        grid-row: auto;
        min-width: 0;
    }

    /* icon (the card surface of the card styles elsewhere) */
    html body.ag2:not(#_):not(#__):not(#___) #chat .mes.smallSysMes > .mes_block::before {
        content: "";
        grid-column: 1;
        grid-row: 1 / span 2;
        align-self: start;
        justify-self: center;
        position: static;
        z-index: auto;
        width: 16px;
        height: 16px;
        margin: 1px 0 0;
        border: 0;
        border-radius: 0;
        box-shadow: none;
        background: var(--ag2-l3);
        -webkit-mask: url("data:image/svg+xml,%3Csvg%20xmlns='http://www.w3.org/2000/svg'%20viewBox='0%200%2024%2024'%20fill='none'%20stroke='%23000'%20stroke-width='1.75'%20stroke-linecap='round'%20stroke-linejoin='round'%3E%3Cpath%20d=%22M15%206a9%209%200%200%200-9%209V3%22/%3E%3Ccircle%20cx=%2218%22%20cy=%226%22%20r=%223%22/%3E%3Ccircle%20cx=%226%22%20cy=%2218%22%20r=%223%22/%3E%3C/svg%3E") center / 16px 16px no-repeat;
        mask: url("data:image/svg+xml,%3Csvg%20xmlns='http://www.w3.org/2000/svg'%20viewBox='0%200%2024%2024'%20fill='none'%20stroke='%23000'%20stroke-width='1.75'%20stroke-linecap='round'%20stroke-linejoin='round'%3E%3Cpath%20d=%22M15%206a9%209%200%200%200-9%209V3%22/%3E%3Ccircle%20cx=%2218%22%20cy=%226%22%20r=%223%22/%3E%3Ccircle%20cx=%226%22%20cy=%2218%22%20r=%223%22/%3E%3C/svg%3E") center / 16px 16px no-repeat;
    }

    html body.ag2:not(#_):not(#__):not(#___) #chat .mes.smallSysMes[is_system="true"] > .mes_block::before {
        -webkit-mask-image: url("data:image/svg+xml,%3Csvg%20xmlns='http://www.w3.org/2000/svg'%20viewBox='0%200%2024%2024'%20fill='none'%20stroke='%23000'%20stroke-width='1.75'%20stroke-linecap='round'%20stroke-linejoin='round'%3E%3Ccircle%20cx=%2212%22%20cy=%2212%22%20r=%2210%22/%3E%3Cpath%20d=%22M12%2016v-4%22/%3E%3Cpath%20d=%22M12%208h.01%22/%3E%3C/svg%3E");
        mask-image: url("data:image/svg+xml,%3Csvg%20xmlns='http://www.w3.org/2000/svg'%20viewBox='0%200%2024%2024'%20fill='none'%20stroke='%23000'%20stroke-width='1.75'%20stroke-linecap='round'%20stroke-linejoin='round'%3E%3Ccircle%20cx=%2212%22%20cy=%2212%22%20r=%2210%22/%3E%3Cpath%20d=%22M12%2016v-4%22/%3E%3Cpath%20d=%22M12%208h.01%22/%3E%3C/svg%3E");
    }

    html body.ag2:not(#_):not(#__):not(#___) #chat .mes.smallSysMes[type="narrator"] > .mes_block::before {
        -webkit-mask-image: url("data:image/svg+xml,%3Csvg%20xmlns='http://www.w3.org/2000/svg'%20viewBox='0%200%2024%2024'%20fill='none'%20stroke='%23000'%20stroke-width='1.75'%20stroke-linecap='round'%20stroke-linejoin='round'%3E%3Cpath%20d=%22M17%205H3%22/%3E%3Cpath%20d=%22M21%2012H8%22/%3E%3Cpath%20d=%22M21%2019H8%22/%3E%3Cpath%20d=%22M3%2012v7%22/%3E%3C/svg%3E");
        mask-image: url("data:image/svg+xml,%3Csvg%20xmlns='http://www.w3.org/2000/svg'%20viewBox='0%200%2024%2024'%20fill='none'%20stroke='%23000'%20stroke-width='1.75'%20stroke-linecap='round'%20stroke-linejoin='round'%3E%3Cpath%20d=%22M17%205H3%22/%3E%3Cpath%20d=%22M21%2012H8%22/%3E%3Cpath%20d=%22M21%2019H8%22/%3E%3Cpath%20d=%22M3%2012v7%22/%3E%3C/svg%3E");
    }

    html body.ag2:not(#_):not(#__):not(#___) #chat .mes.smallSysMes[type="comment"] > .mes_block::before {
        -webkit-mask-image: url("data:image/svg+xml,%3Csvg%20xmlns='http://www.w3.org/2000/svg'%20viewBox='0%200%2024%2024'%20fill='none'%20stroke='%23000'%20stroke-width='1.75'%20stroke-linecap='round'%20stroke-linejoin='round'%3E%3Cpath%20d=%22M13.4%202H6a2%202%200%200%200-2%202v16a2%202%200%200%200%202%202h12a2%202%200%200%200%202-2v-7.4%22/%3E%3Cpath%20d=%22M2%206h4%22/%3E%3Cpath%20d=%22M2%2010h4%22/%3E%3Cpath%20d=%22M2%2014h4%22/%3E%3Cpath%20d=%22M2%2018h4%22/%3E%3Cpath%20d=%22M21.378%205.626a1%201%200%201%200-3.004-3.004l-5.01%205.012a2%202%200%200%200-.506.854l-.837%202.87a.5.5%200%200%200%20.62.62l2.87-.837a2%202%200%200%200%20.854-.506z%22/%3E%3C/svg%3E");
        mask-image: url("data:image/svg+xml,%3Csvg%20xmlns='http://www.w3.org/2000/svg'%20viewBox='0%200%2024%2024'%20fill='none'%20stroke='%23000'%20stroke-width='1.75'%20stroke-linecap='round'%20stroke-linejoin='round'%3E%3Cpath%20d=%22M13.4%202H6a2%202%200%200%200-2%202v16a2%202%200%200%200%202%202h12a2%202%200%200%200%202-2v-7.4%22/%3E%3Cpath%20d=%22M2%206h4%22/%3E%3Cpath%20d=%22M2%2010h4%22/%3E%3Cpath%20d=%22M2%2014h4%22/%3E%3Cpath%20d=%22M2%2018h4%22/%3E%3Cpath%20d=%22M21.378%205.626a1%201%200%201%200-3.004-3.004l-5.01%205.012a2%202%200%200%200-.506.854l-.837%202.87a.5.5%200%200%200%20.62.62l2.87-.837a2%202%200%200%200%20.854-.506z%22/%3E%3C/svg%3E");
    }

    /* no portrait (echo / whisper), no model meta, no swipe capsule (ST: never swipeable) */
    html body.ag2:not(#_):not(#__):not(#___) #chat .mes.smallSysMes > .mes_block::after,
    html body.ag2:not(#_):not(#__):not(#___) #chat .mes.smallSysMes::after,
    html body.ag2:not(#_):not(#__):not(#___) #chat .mes.smallSysMes > .swipeRightBlock::before {
        content: none !important;
    }

    html body.ag2:not(#_):not(#__):not(#___) #chat .mes.smallSysMes :is(.swipe_left, .swipe_right, .swipes-counter) {
        display: none !important;
    }

    /* caption: the sender name as a section label (11.5 / 620, l3); also when ag2-cont */
    html body.ag2:not(#_):not(#__):not(#___) #chat .mes.smallSysMes .ch_name > :first-child {
        display: flex !important;
        align-items: center;
        min-height: 0;
        margin: 0 0 2px;
        padding: 0;
        overflow: hidden;
    }

    /* document style hides .name_text with !important (toggle-dependent.css) */
    html body.ag2:not(#_):not(#__):not(#___) #chat .mes.smallSysMes .ch_name .name_text {
        display: inline !important;
        color: var(--ag2-l3) !important;
        font-size: var(--ag2-fs-section) !important;
        font-weight: 620 !important;
        letter-spacing: 0.02em;
    }

    html body.ag2:not(#_):not(#__):not(#___) #chat .mes.smallSysMes:not(:has(.edit_textarea)) .ch_name :is(.timestamp, .timestamp-icon, .mes_ghost) {
        display: none !important;
    }

    html body.ag2:not(#_):not(#__):not(#___) #chat .mes.smallSysMes .mes_text {
        min-height: 0 !important;
        color: rgba(255, 255, 255, 0.88) !important;
        font-size: 14.5px !important;
        line-height: 1.6 !important;
        letter-spacing: 0;
        text-align: left;
    }

    html body.ag2:not(#_):not(#__):not(#___) #chat .mes.smallSysMes .mes_text :is(img, video, iframe, table, pre) {
        max-width: 100%;
    }

    /* action row: a floating bar under the capsule, on hover / focus (touch: after a tap).
       Solid fill, no blur (§5.10). Never permanently shown, also on the last message. */
    html body.ag2:not(#_):not(#__):not(#___) #chat .mes.smallSysMes > .mes_block > .ch_name > .mes_buttons {
        /* auto placement: an absolutely positioned grid child is laid out against its grid
           area, and the bar must centre on the whole capsule */
        grid-column: auto;
        position: absolute !important;
        top: calc(100% - 8px);
        left: 50%;
        z-index: 10;
        flex-wrap: wrap;
        justify-content: center;
        width: max-content;
        min-width: 0;
        max-width: min(420px, calc(100vw - 28px));
        margin: 0 !important;
        padding: 3px !important;
        border-radius: 12px;
        background: rgba(44, 44, 51, 0.97);
        box-shadow: var(--ag2-rim), var(--ag2-sh2);
        transform: translateX(-50%);
    }

    html body.ag2:not(#_):not(#__):not(#___) #chat .mes.smallSysMes:not(:hover):not(:focus-within) .mes_buttons {
        opacity: 0 !important;
        pointer-events: none;
    }

    /* “更多” opens below the bar, centred (it would cover the receipt above it) */
    html body.ag2:not(.expandMessageActions):not(#_):not(#__):not(#___) #chat .mes.smallSysMes .mes_buttons > .extraMesButtons {
        position: absolute !important;
        z-index: 10;
        flex-wrap: wrap !important;
        gap: 2px;
        width: max-content;
        padding: 5px !important;
        border-radius: 14px;
        background: rgba(44, 44, 51, 0.97) !important;
        box-shadow: var(--ag2-rim), var(--ag2-sh2) !important;
        overflow: visible !important;
        top: calc(100% + 6px);
        bottom: auto;
        left: 50%;
        max-width: min(330px, calc(100vw - 28px));
        transform: translateX(-50%);
    }

    /* edit mode: a plain full-width block — name, textarea, ST's edit buttons */
    html body.ag2:not(#_):not(#__):not(#___) #chat .mes.smallSysMes:has(.edit_textarea) > .mes_block {
        justify-self: stretch;
        grid-template-columns: minmax(0, 1fr);
        width: auto;
        max-width: none;
        padding: 0 !important;
        border-radius: 0;
        background: none;
        box-shadow: none;
    }

    html body.ag2:not(#_):not(#__):not(#___) #chat .mes.smallSysMes:has(.edit_textarea) > .mes_block::before {
        content: none;
    }

    html body.ag2:not(#_):not(#__):not(#___) #chat .mes.smallSysMes:has(.edit_textarea) > .mes_block > *,
    html body.ag2:not(#_):not(#__):not(#___) #chat .mes.smallSysMes:has(.edit_textarea) > .mes_block > .ch_name > * {
        grid-column: 1;
    }

    html body.ag2:not(#_):not(#__):not(#___) #chat .mes.smallSysMes:has(.edit_textarea) .ch_name > :first-child {
        min-height: 28px;
        margin: 0 0 6px;
    }

    html body.ag2:not(#_):not(#__):not(#___) #chat .mes.smallSysMes:has(.edit_textarea) .ch_name .name_text {
        color: var(--ag2-l1) !important;
        font-size: 13.5px !important;
        font-weight: 640 !important;
        letter-spacing: -0.01em;
    }

    html body.ag2:not(#_):not(#__):not(#___) #chat .mes.smallSysMes:has(.edit_textarea) .mes_text {
        font-size: var(--ag2-read-size) !important;
    }

    html body.ag2:not(#_):not(#__):not(#___) #chat .mes.smallSysMes .mes_edit_buttons {
        order: 9; /* after the text, like every other message */
        justify-self: start;
        margin: 6px 0 0 !important;
    }
}

/* == 5.3c-C · Small system messages — variant C: timeline divider (user pick, 2026-11-12) ==
   Appended over §5.3c (four ids beat it): the receipt is a centred divider — hairline ·
   [icon] option text · hairline — no surface, no sender caption. §5.3c stays intact
   underneath: this block is guarded by :not(:has(.edit_textarea)), so edit mode, the
   floating action bar and the delete checkbox keep §5.3c's behaviour. Delete this block
   to return to the A capsule; B lives in tools/ag2/r3a-variants/B.css.
   The receipt is a *post-choice echo*, so the option is one line + ellipsis (the card the
   user picked from is untouched). When the text actually truncates, a “▾ 展开” affordance
   shows on hover / focus / after a tap; clicking the receipt (reading.js) toggles
   ag2-ssb-open, which clamps the text to 1 line or lets it wrap. */

@media screen {
    html body.ag2:not(#_):not(#__):not(#___):not(#____) #chat .mes.smallSysMes:not(:has(.edit_textarea)) {
        grid-template-columns:
            [outer card in] minmax(24px, 1fr) [mid] minmax(0, 560px) [r] minmax(24px, 1fr) [pr end];
        column-gap: 14px;
        margin-bottom: 20px !important;
    }

    html body.ag2:not(#_):not(#__):not(#___):not(#____) #chat .mes.smallSysMes:not(:has(.edit_textarea)) > .mes_block {
        grid-column: mid;
        justify-self: center;
        column-gap: 7px;
        max-width: 100%;
        padding: 2px 14px 2px 0 !important;
        border-radius: 0;
        background: none;
        box-shadow: none;
    }

    /* the two hairlines: .mes::after and .swipeRightBlock::before (both unused on a
       small system message; §5.3c turned them off, four ids turn them back on).
       -webkit-line-clamp needs a -webkit-box, so the clamp lives on .mes_text itself. */
    html body.ag2:not(#_):not(#__):not(#___):not(#____) #chat .mes.smallSysMes:not(:has(.edit_textarea))::after,
    html body.ag2:not(#_):not(#__):not(#___):not(#____) #chat .mes.smallSysMes:not(:has(.edit_textarea)) > .swipeRightBlock::before {
        content: "" !important;
        display: block;
        grid-row: text;
        align-self: start;
        margin: 11px 0 0;   /* the text line's optical centre (13.5px × 1.5 ≈ 20px) */
        height: 0.5px;
        opacity: 1 !important; /* override the ordinary message's hover-only meta */
        border-radius: 0;
        background: var(--ag2-sep-strong);
        z-index: auto;
    }

    html body.ag2:not(#_):not(#__):not(#___):not(#____) #chat .mes.smallSysMes:not(:has(.edit_textarea))::after {
        grid-column: r;
        max-width: none;
    }

    html body.ag2:not(#_):not(#__):not(#___):not(#____) #chat .mes.smallSysMes:not(:has(.edit_textarea)) > .swipeRightBlock::before {
        grid-column: in;
    }

    html body.ag2:not(#_):not(#__):not(#___):not(#____) #chat .mes.smallSysMes:not(:has(.edit_textarea)) > .mes_block::before {
        width: 15px;
        height: 15px;
        margin-top: 2px;
        -webkit-mask-size: 15px 15px;
        mask-size: 15px 15px;
    }

    /* no sender caption on the divider */
    html body.ag2:not(#_):not(#__):not(#___):not(#____) #chat .mes.smallSysMes:not(:has(.edit_textarea)) .ch_name > :first-child {
        display: none !important;
    }

    /* touch: the tap pins the bar open (ag2-ssb-bar, reading.js) — :hover alone would hide
       it the moment a bar button is tapped, closing ST's “更多” popup at once */
    html body.ag2:not(#_):not(#__):not(#___):not(#____) #chat .mes.smallSysMes.ag2-ssb-bar:not(:hover):not(:focus-within) .mes_buttons {
        opacity: 1 !important;
        pointer-events: auto;
    }

    /* one line + ellipsis when collapsed; wraps when ag2-ssb-open (reading.js toggles it
       on click; double-click / selection / the buttons never toggle) */
    html body.ag2:not(#_):not(#__):not(#___):not(#____) #chat .mes.smallSysMes:not(:has(.edit_textarea)) .mes_text {
        color: var(--ag2-l2) !important;
        font-size: 13.5px !important;
        font-weight: 520 !important;
        line-height: 1.5 !important;
        text-align: center;
        max-width: 100%;
        display: -webkit-box;
        -webkit-box-orient: vertical;
        -webkit-line-clamp: 1;
        overflow: hidden;
        overflow-wrap: anywhere;
        cursor: pointer;
        transition: color var(--ag2-dur) ease;
    }

    html body.ag2:not(#_):not(#__):not(#___):not(#____) #chat .mes.smallSysMes:not(:has(.edit_textarea)):hover .mes_text,
    html body.ag2:not(#_):not(#__):not(#___):not(#____) #chat .mes.smallSysMes:not(:has(.edit_textarea)):focus-within .mes_text {
        color: var(--ag2-l1) !important;
    }

    html body.ag2:not(#_):not(#__):not(#___):not(#____) #chat .mes.smallSysMes:not(:has(.edit_textarea)).ag2-ssb-open .mes_text {
        -webkit-line-clamp: unset;
        display: block;
        overflow: visible;
        overflow-wrap: anywhere;
        white-space: normal;
        text-align: left;
    }

    html body.ag2:not(#_):not(#__):not(#___):not(#____) #chat .mes.smallSysMes:not(:has(.edit_textarea)).ag2-ssb-open > .mes_block {
        width: 100%;
    }

    /* the hairlines fade out while expanded (the text is no longer “on a line”) */
    html body.ag2:not(#_):not(#__):not(#___):not(#____) #chat .mes.smallSysMes:not(:has(.edit_textarea)).ag2-ssb-open::after,
    html body.ag2:not(#_):not(#__):not(#___):not(#____) #chat .mes.smallSysMes:not(:has(.edit_textarea)).ag2-ssb-open > .swipeRightBlock::before {
        opacity: 0 !important;
    }

    /* a chevron hint appears only when the text really truncates: reading.js marks
       data-ag2-clamp="1" on .mes_text when scrollHeight > clientHeight */
    html body.ag2:not(#_):not(#__):not(#___):not(#____) #chat .mes.smallSysMes:not(:has(.edit_textarea)) .mes_text::after {
        content: "";
        display: none;
    }

    html body.ag2:not(#_):not(#__):not(#___):not(#____) #chat .mes.smallSysMes[data-ag2-clamp="1"]:not(:has(.edit_textarea)) > .mes_block::after {
        content: "⌄" !important;
        position: absolute;
        top: 0;
        right: 0;
        width: 10px;
        height: 20px;
        background: none;
        mask: none;
        -webkit-mask: none;
        opacity: 1;
        z-index: auto;
        color: var(--ag2-l3);
        font-size: 12px;
        pointer-events: none;
    }

    html body.ag2:not(#_):not(#__):not(#___):not(#____) #chat .mes.smallSysMes:not(:has(.edit_textarea)).ag2-ssb-open > .mes_block::after {
        content: "⌃" !important;
    }

    /* touch needs no hover: after a tap the hint stays (sticky :hover on iOS) */
    html body.ag2:not(#_):not(#__):not(#___):not(#____) #chat .mes.smallSysMes:not(:has(.edit_textarea)) .mes_text[data-ag2-clamp="0"]::after {
        content: none;
    }
}

/* == 5.4 · Input island (§5.4) == */
/* ST's #form_sheld floats at the bottom of #sheld and the chat scrolls under it.
   Inside: the QR capsule row, then #nonQRFormItems = the island:
   [+] [textarea] [other extension buttons] [model] [send / stop].
   §19a multi-line behaviour: the island grows with the textarea up to 40dvh, the
   buttons stay on the bottom line. Both layouts since P5; §5.9 re-places it on phones. */

@media screen { /* desktop + phone since P5 (§5.9 overrides the geometry) */
    html body.ag2:not(#_):not(#__) #form_sheld {
        position: absolute !important;
        left: 0;
        right: 0;
        bottom: 0;
        z-index: 31;
        width: min(calc(100% - 48px), 760px) !important;
        margin: 0 auto !important;
        padding: 0 0 14px !important;
        border: 0 !important;
        background: none !important;
        box-shadow: none !important;
        white-space: normal;
    }

    html body.ag2:not(#_):not(#__) #send_form {
        display: flex !important;
        flex-wrap: wrap;
        align-items: center;
        gap: 10px 8px;
        width: 100%;
        margin: 0 !important;
        padding: 0 !important;
        border: 0 !important;
        border-radius: 0 !important;
        outline: 0 !important;
        background: none !important;
        box-shadow: none !important;
        -webkit-backdrop-filter: none !important;
        backdrop-filter: none !important;
    }

    /* QR capsules: one row, horizontal scroll, faded ends (§5.4). Small controls:
       solid translucent fill, no blur (§7). */
    html body.ag2:not(#_):not(#__) :is(#qr--bar, #qr-bar):not(:has(button, .qr--button)) {
        display: none !important;
    }

    html body.ag2:not(#_):not(#__) :is(#qr--bar, #qr-bar) {
        display: flex !important;
        flex: 0 1 auto;
        min-width: 0;
        max-width: 100%;
        margin: 0 !important;
        padding: 0 2px !important;
        border: 0 !important;
        background: none !important;
        box-shadow: none !important;
        overflow-x: auto;
        overflow-y: hidden;
        scrollbar-width: none;
        -webkit-mask-image: linear-gradient(to right, transparent 0, #000 6px, #000 calc(100% - 18px), transparent 100%);
        mask-image: linear-gradient(to right, transparent 0, #000 6px, #000 calc(100% - 18px), transparent 100%);
    }

    html body.ag2:not(#_):not(#__) :is(#qr--bar, #qr-bar)::-webkit-scrollbar {
        display: none;
    }

    /* the QR extension writes flex-wrap:wrap inline */
    html body.ag2:not(#_):not(#__) :is(#qr--bar, #qr-bar) .qr--buttons {
        display: flex !important;
        flex-wrap: nowrap !important;
        justify-content: flex-start !important;
        gap: 8px !important;
        padding-right: 14px;
    }

    html body.ag2:not(#_):not(#__) :is(#qr--bar, #qr-bar) :is(.qr--button, .menu_button) {
        display: inline-flex !important;
        flex: none !important;
        align-items: center;
        gap: 6px;
        height: 30px !important;
        min-height: 30px;
        margin: 0 !important;
        padding: 0 13px !important;
        border: 0 !important;
        border-radius: 15px !important;
        background: rgba(48, 48, 56, 0.78) !important;
        box-shadow: var(--ag2-rim) !important;
        color: var(--ag2-l1) !important;
        font: 560 12.5px/1 var(--ag2-font) !important;
        white-space: nowrap !important;
        opacity: 1 !important;
        filter: none !important;
        -webkit-backdrop-filter: none !important;
        backdrop-filter: none !important;
        transition: background-color var(--ag2-dur) ease;
    }

    html body.ag2:not(#_):not(#__) :is(#qr--bar, #qr-bar) :is(.qr--button, .menu_button):hover {
        background: rgba(62, 62, 72, 0.86) !important;
    }

    /* ghost “+ 快速回复” after the capsules (only when there are capsules) */
    html body.ag2:not(#_):not(#__) #ag2-qr-add {
        display: none;
        flex: none;
        align-items: center;
        gap: 5px;
        height: 30px;
        margin: 0;
        padding: 0 10px;
        border: 0;
        border-radius: 15px;
        background: none;
        color: var(--ag2-l3);
        font: 520 12.5px/1 var(--ag2-font);
        white-space: nowrap;
        cursor: pointer;
    }

    html body.ag2:not(#_):not(#__) #send_form:has(:is(#qr--bar, #qr-bar) :is(button, .qr--button)) #ag2-qr-add {
        display: inline-flex;
    }

    html body.ag2:not(#_):not(#__) #ag2-qr-add:hover {
        background: var(--ag2-f4);
        color: var(--ag2-l1);
    }

    html body.ag2:not(#_):not(#__) #send_form #file_form {
        width: 100%;
    }

    /* the island: 760 wide, 54 high at one line, floating glass (one of the five blur
       layers, §7) */
    html body.ag2:not(#_):not(#__) #send_form #nonQRFormItems {
        display: flex !important;
        align-items: flex-end !important;
        gap: 4px !important;
        width: 100%;
        min-height: 54px !important;
        padding: 7px !important;
        border: 0 !important;
        /* §19a: radius = half the one-line height → a capsule at one line, a rounded
           rectangle (not an ellipse) once it grows */
        border-radius: 27px !important;
        background: var(--ag2-mat-float) !important;
        -webkit-backdrop-filter: var(--ag2-blur-float) !important;
        backdrop-filter: var(--ag2-blur-float) !important;
        box-shadow: var(--ag2-rim), var(--ag2-sh2) !important;
        font-size: 15px;
        transition: box-shadow var(--ag2-dur) ease;
    }

    html body.ag2:not(#_):not(#__) #send_form.ag2-multi #nonQRFormItems {
        border-radius: 24px !important;
    }

    html body.ag2:not(#_):not(#__) #send_form:focus-within #nonQRFormItems {
        box-shadow: inset 0 0 0 0.5px rgba(255, 255, 255, 0.22), inset 0 1px 0 rgba(255, 255, 255, 0.09), var(--ag2-sh2) !important;
    }

    /* §19a: the textarea grows (ST's field-sizing / inline height untouched), capped
       at 40dvh, then scrolls inside. ST's 3px top border is its slash-command progress
       bar; it stays, only transparent. */
    html body.ag2:not(#_):not(#__) #send_form #send_textarea {
        align-self: stretch;
        min-height: 40px !important;
        max-height: 40vh !important;
        max-height: 40dvh !important;
        margin: 0 !important;
        padding: 6px 8px 9px !important;
        border-right: 0 !important;
        border-bottom: 0 !important;
        border-left: 0 !important;
        border-top-color: transparent;
        background: none !important;
        box-shadow: none !important;
        color: var(--ag2-l1) !important;
        font: 400 15px/22px var(--ag2-font) !important;
        letter-spacing: 0;
        caret-color: var(--ag2-accent);
        resize: none !important;
    }

    html body.ag2:not(#_):not(#__) #send_form #send_textarea::placeholder {
        color: var(--ag2-l3) !important;
        text-align: left !important;
    }

    /* not connected: “未连接 API — 点此连接” (composer.js), in red */
    html body.ag2:not(#_):not(#__) #send_form.no-connection #send_textarea::placeholder {
        color: var(--ag2-red) !important;
    }

    /* button groups sit on the bottom line (§19a) */
    html body.ag2:not(#_):not(#__) #send_form :is(#leftSendForm, #rightSendForm) {
        display: flex !important;
        flex-wrap: nowrap !important;
        align-self: flex-end !important;
        align-items: center !important;
        gap: 2px !important;
        min-height: 40px !important;
        margin: 0 !important;
        padding: 0 !important;
    }

    /* ☰ and the wand are replaced by the + menu; they stay in the DOM (§5.4) */
    html body.ag2:not(#_):not(#__) #options_button,
    html body.ag2:not(#_):not(#__) #extensionsMenuButton {
        display: none !important;
    }

    /* other extensions' buttons in the island: 32px ghost icons (display stays ST's) */
    html body.ag2:not(#_):not(#__) #leftSendForm > :not(#ag2-plus),
    html body.ag2:not(#_):not(#__) #rightSendForm > :not(#ag2-model):not(#send_but):not(#mes_stop) {
        align-items: center;
        justify-content: center;
        width: 32px !important;
        height: 32px !important;
        min-width: 32px !important;
        min-height: 32px !important;
        margin: 0 !important;
        padding: 0 !important;
        border: 0 !important;
        border-radius: 16px !important;
        background: none !important;
        box-shadow: none !important;
        color: var(--ag2-l2) !important;
        font-size: 15px !important;
        opacity: 1 !important;
        filter: none !important;
        transition: background-color var(--ag2-dur) ease, color var(--ag2-dur) ease;
    }

    html body.ag2:not(#_):not(#__) #leftSendForm > :not(#ag2-plus):hover,
    html body.ag2:not(#_):not(#__) #rightSendForm > :not(#ag2-model):not(#send_but):not(#mes_stop):hover {
        background: var(--ag2-f4) !important;
        color: var(--ag2-l1) !important;
    }

    /* keyboard focus ring (§8): 3px accent, only for :focus-visible */
    html body.ag2:not(#_):not(#__) :is(#ag2-plus, #ag2-model, #ag2-qr-add):focus {
        outline: none;
    }

    html body.ag2:not(#_):not(#__) :is(#ag2-plus, #ag2-model, #ag2-qr-add):focus-visible {
        outline: 3px solid var(--ag2-accent);
        outline-offset: 1px;
    }

    /* + (40 circle) → × while its menu is open */
    html body.ag2:not(#_):not(#__) #ag2-plus {
        display: inline-flex;
        flex: none;
        align-items: center;
        justify-content: center;
        width: 40px;
        height: 40px;
        margin: 0;
        padding: 0;
        border: 0;
        border-radius: 20px;
        background: var(--ag2-f4);
        color: var(--ag2-l1);
        cursor: pointer;
        transition: background-color var(--ag2-dur) ease;
    }

    html body.ag2:not(#_):not(#__) #ag2-plus:hover { background: var(--ag2-f3); }
    html body.ag2:not(#_):not(#__) #ag2-plus.ag2-open { background: rgba(255, 255, 255, 0.16); }
    html body.ag2:not(#_):not(#__) #ag2-plus .ag2-x-i,
    html body.ag2:not(#_):not(#__) #ag2-plus.ag2-open .ag2-plus-i { display: none; }
    html body.ag2:not(#_):not(#__) #ag2-plus.ag2-open .ag2-x-i { display: block; }

    /* model capsule: ghost pill, model name (ellipsis), red dot when not connected */
    html body.ag2:not(#_):not(#__) #ag2-model {
        display: inline-flex;
        flex: 0 1 auto;
        order: 1;
        align-items: center;
        gap: 5px;
        min-width: 0;
        max-width: 240px;
        height: 32px;
        margin: 0 2px 0 0;
        padding: 0 9px 0 11px;
        border: 0;
        border-radius: 16px;
        background: none;
        color: var(--ag2-l2);
        font: 520 12.5px/1 var(--ag2-font);
        white-space: nowrap;
        cursor: pointer;
        transition: background-color var(--ag2-dur) ease, color var(--ag2-dur) ease;
    }

    html body.ag2:not(#_):not(#__) #ag2-model:hover,
    html body.ag2:not(#_):not(#__) #ag2-model.ag2-open {
        background: var(--ag2-f4);
        color: var(--ag2-l1);
    }

    html body.ag2:not(#_):not(#__) #ag2-model .ag2-model-name {
        min-width: 0;
        overflow: hidden;
        text-overflow: ellipsis;
    }

    html body.ag2:not(#_):not(#__) #ag2-model :is(.ag2-model-zap, .ag2-model-chev) {
        color: var(--ag2-l3);
    }

    html body.ag2:not(#_):not(#__) #ag2-model .ag2-model-dot {
        display: none;
        flex: none;
        width: 7px;
        height: 7px;
        border-radius: 50%;
        background: var(--ag2-red);
    }

    html body.ag2:not(#_):not(#__) #ag2-model.ag2-off .ag2-model-dot { display: block; }
    html body.ag2:not(#_):not(#__) #ag2-model.ag2-off .ag2-model-zap { display: none; }

    /* send (40 circle): grey while empty; accent + a soft accent shadow with text.
       display is left to ST (displayNone / data-generating). */
    html body.ag2:not(#_):not(#__) #send_form #send_but {
        order: 2;
        align-items: center;
        justify-content: center;
        width: 40px !important;
        height: 40px !important;
        min-width: 40px !important;
        margin: 0 !important;
        padding: 0 !important;
        border: 0 !important;
        border-radius: 20px !important;
        background: var(--ag2-f3) !important;
        box-shadow: none !important;
        color: var(--ag2-l3) !important;
        font-size: 17px !important;
        opacity: 1 !important;
        filter: none !important;
        transition: background-color var(--ag2-dur) ease, color var(--ag2-dur) ease, box-shadow var(--ag2-dur) ease;
    }

    /* paper plane → arrow-up (Font Awesome glyph) */
    html body.ag2:not(#_):not(#__) #send_form #send_but::before {
        content: "\f062";
    }

    html body.ag2:not(#_):not(#__) #send_form.ag2-has-text #send_but {
        background: var(--ag2-accent) !important;
        box-shadow: 0 2px 10px color-mix(in srgb, var(--ag2-accent) 38%, transparent), inset 0 0.5px 0 rgba(255, 255, 255, 0.3) !important;
        color: #fff !important;
    }

    html body.ag2:not(#_):not(#__) #send_form.ag2-has-text #send_but:hover {
        background: var(--ag2-accent-hover) !important;
    }

    /* stop (ST shows it while generating): the same circle, light, square glyph */
    html body.ag2:not(#_):not(#__) #send_form #mes_stop {
        order: 2;
        align-items: center;
        justify-content: center;
        place-self: auto;
        width: 40px !important;
        height: 40px !important;
        min-width: 40px;
        margin: 0 !important;
        padding: 0 !important;
        border: 0;
        border-radius: 20px;
        background: var(--ag2-l1);
        color: #1c1c1e;
        opacity: 1 !important;
        cursor: pointer;
    }

    html body.ag2:not(#_):not(#__) #send_form #mes_stop > i {
        color: inherit;
        font-size: 13px;
    }

    html body.ag2:not(#_):not(#__) #send_form #mes_stop > i::before {
        content: "\f04d";
    }

