/* == 5.5 · Settings window (§5.5, §9.2 #1/#2) == */
/* Frame (#ag2-set-dim 3001, #ag2-settings 3002) is a body child built on first open by
   shell/settings.js. The eight ST drawers never move: while body.ag2-set-open, the open
   one becomes a fixed box over the window's content area. They live in
   #top-settings-holder (z 3005), so they paint above the frame without any z juggling. */

html body.ag2 {
    --ag2-win-w: min(1080px, calc(100vw - 64px));
    --ag2-win-h: min(742px, calc(100vh - 48px));
    --ag2-win-x: calc((100vw - var(--ag2-win-w)) / 2);
    --ag2-win-y: calc((100vh - var(--ag2-win-h)) / 2);
    --ag2-set-nav: 252px;
    --ag2-set-head: 86px;
}

html body.ag2:not(#_):not(#__) :is(#ag2-set-dim, #ag2-settings)[hidden] {
    display: none !important;
}

html body.ag2:not(#_):not(#__) #ag2-set-dim {
    position: fixed;
    inset: 0;
    z-index: var(--ag2-z-window-backdrop);
    background: rgba(0, 0, 0, 0.44);
    animation: ag2-set-fade var(--ag2-dur) ease;
}

html body.ag2:not(#_):not(#__) #ag2-settings {
    position: fixed;
    left: var(--ag2-win-x);
    top: var(--ag2-win-y);
    z-index: var(--ag2-z-window);
    display: grid;
    grid-template-columns: var(--ag2-set-nav) minmax(0, 1fr);
    width: var(--ag2-win-w);
    height: var(--ag2-win-h);
    overflow: hidden;
    border-radius: var(--ag2-r-window);
    background: var(--ag2-mat-window);
    -webkit-backdrop-filter: var(--ag2-blur-window);
    backdrop-filter: var(--ag2-blur-window);
    box-shadow: var(--ag2-rim), var(--ag2-sh3);
    color: var(--ag2-l1);
    font-family: var(--ag2-font);
    font-size: var(--ag2-fs-body);
    animation: ag2-set-in var(--ag2-dur-panel) var(--ag2-ease-sheet);
}

@keyframes ag2-set-fade { from { opacity: 0; } }
@keyframes ag2-set-in { from { opacity: 0; transform: scale(0.985); } }

