/* --- ST drawers inside the window (rule 1: CSS only, nodes untouched) --- */
@media screen { /* desktop + phone since P5 (§5.9 overrides the geometry) */
    html body.ag2.ag2-set-open:not(#_):not(#__) :is(#rm_api_block, #left-nav-panel, #AdvancedFormatting, #WorldInfo, #PersonaManagement, #Backgrounds, #user-settings-block, #rm_extensions_block).openDrawer {
        position: fixed !important;
        inset: auto !important;
        top: calc(var(--ag2-win-y) + var(--ag2-set-head)) !important;
        left: calc(var(--ag2-win-x) + var(--ag2-set-nav)) !important;
        z-index: 1 !important;
        box-sizing: border-box !important;
        width: calc(var(--ag2-win-w) - var(--ag2-set-nav)) !important;
        height: calc(var(--ag2-win-h) - var(--ag2-set-head)) !important;
        min-width: 0 !important;
        max-width: none !important;
        min-height: 0 !important;
        max-height: none !important;
        margin: 0 !important;
        /* same 28px gutters as the shell pages (the scrollbar is an overlay, it takes no
           width); the last 20px fade out so a page cut by the window edge reads as
           “scrolls on”, and at the very end only the bottom padding is under the fade */
        padding: 0 28px 24px 28px !important;
        overflow-x: hidden !important;
        overflow-y: auto !important;
        -webkit-mask-image: linear-gradient(to bottom, #000 calc(100% - 20px), transparent) !important;
        mask-image: linear-gradient(to bottom, #000 calc(100% - 20px), transparent) !important;
        border: 0 !important;
        border-radius: 0 0 var(--ag2-r-window) 0 !important;
        background: transparent !important;
        -webkit-backdrop-filter: none !important;
        backdrop-filter: none !important;
        box-shadow: none !important;
        transform: none !important;
        /* ST animates height from 0 (@starting-style); inside the window the page simply
           fades with the frame */
        transition: none !important;
        animation: ag2-set-fade var(--ag2-dur) ease !important;
        pointer-events: auto !important;
    }

    /* 生成参数 is a flex column whose .scrollableInner scrolls; keep that, fill the box */
    html body.ag2.ag2-set-open:not(#_):not(#__) #left-nav-panel.openDrawer {
        display: flex !important;
        flex-direction: column !important;
        padding-right: 0 !important;
        overflow-y: hidden !important;
        -webkit-mask-image: none !important;
        mask-image: none !important;
    }

    html body.ag2.ag2-set-open:not(#_):not(#__) #left-nav-panel.openDrawer > .scrollableInner {
        flex: 1 1 auto !important;
        height: auto !important;
        min-height: 0 !important;
        padding: 0 28px 24px 0 !important;
        overflow-y: auto !important;
        -webkit-mask-image: linear-gradient(to bottom, #000 calc(100% - 20px), transparent) !important;
        mask-image: linear-gradient(to bottom, #000 calc(100% - 20px), transparent) !important;
    }

    /* Inspector (ST right panel) hides while the window is up (§9.2 #2) */
    html body.ag2.ag2-set-open:not(#_):not(#__) #right-nav-panel {
        visibility: hidden !important;
    }

    /* R1 · no native flash. ST closes a drawer by swapping .openDrawer for .closedDrawer and
       lets `transition: height, display allow-discrete` (2 × animation_duration) play, so the
       closing drawer stays display:block for ~250ms — without .openDrawer it matched none of
       the rules above and showed at ST's own spot with ST's own look (over the window when a
       page was switched, over the chat when the window closed; on phones a full-screen
       blurred sheet). A running transition also beats `display: none !important`, hence
       `transition: none`. The window / sheet is what animates; the drawer just goes. */
    html body.ag2:not(#_):not(#__) :is(#rm_api_block, #left-nav-panel, #AdvancedFormatting, #WorldInfo, #PersonaManagement, #Backgrounds, #user-settings-block, #rm_extensions_block, #right-nav-panel):not(.openDrawer) {
        display: none !important;
        transition: none !important;
        animation: none !important;
    }

    /* A settings drawer that is open while the window is not (ST re-opened a pinned drawer
       at start; the frames between a theme switch and the window adopting the drawer; the
       window closing): never painted at ST's spot. The drawer observer (shell/index.js)
       opens the window for it, which makes the rules above apply. */
    html body.ag2:not(.ag2-set-open):not(#_):not(#__) :is(#rm_api_block, #left-nav-panel, #AdvancedFormatting, #WorldInfo, #PersonaManagement, #Backgrounds, #user-settings-block, #rm_extensions_block).openDrawer {
        visibility: hidden !important;
        transition: none !important;
        animation: none !important;
        pointer-events: none !important;
    }
}

