/* hit: accent ring + soft fill, blinks for 1.2s; reduced motion → static ring only.
   Explicit here: the §14 media-query catch-all is less specific than this rule, so it
   would not shorten the blink under the system setting. */
/* the ring is an inset outline, not box-shadow: buttons / fields set their own box-shadow
   with !important (添加背景 showed no ring at all). No !important on outline here — an
   !important value would also beat the keyframes and stop the blink; an extra id-level
   :not() outranks ST's own outline rules instead. */
html body.ag2:not(#_):not(#__):not(#___) .ag2-hit {
    border-radius: 8px;
    outline: 2px solid var(--ag2-accent);
    outline-offset: -2px;
    animation: ag2-hit 1.2s ease-in-out both !important;
}

html body.ag2.reduced-motion:not(#_):not(#__):not(#___) .ag2-hit {
    animation: none !important;
}

@media (prefers-reduced-motion: reduce) {
    html body.ag2:not(#_):not(#__):not(#___) .ag2-hit {
        animation: none !important;
    }
}

@keyframes ag2-hit {
    0%, 50%, 100% { outline-color: var(--ag2-accent); background-color: var(--ag2-accent-soft); }
    25%, 75% { outline-color: transparent; background-color: transparent; }
}

