/* == 5.6 · Inspector (§5.6, §4, §9.2 #2/#3) == */
/* The inspector is ST's #right-nav-panel (never moved): this section only places it and
   chooses which block shows. inspector.js writes panel[data-ag2-insp] =
   char | group | chat | create | group_create | empty | pending after checking that ST's
   editor belongs to the open chat — the form shows only for "char" / "group" (never a
   stale editor: ST autosaves whatever #avatar_url_pole points to). Phones (§5.9): the same
   panel as a full-screen sheet. */

html body.ag2.ag2-insp-open {
    /* what the floating inspector covers at medium widths (title capsule room) */
    --ag2-insp-cover: calc(var(--ag2-insp-w) + var(--ag2-inset));
}

@media (min-width: 1360px) {
    /* wide: the inspector takes its own column; the chat narrows (§4) */
    html body.ag2.ag2-insp-open {
        --ag2-sheld-right: calc(var(--ag2-inset) * 2 + var(--ag2-insp-w));
        --ag2-insp-cover: 0px;
    }
}

@media screen { /* desktop + phone since P5 (§5.9 overrides the geometry) */
    html body.ag2:not(#_):not(#__) #sheld {
        transition: left var(--ag2-dur-panel) var(--ag2-ease-sheet), right var(--ag2-dur-panel) var(--ag2-ease-sheet);
    }

    /* the tool capsule sits left of the inspector in both forms; the title capsule
       leaves room for it */
    html body.ag2.ag2-insp-open #ag2-tools {
        right: calc(var(--ag2-inset) * 3 + var(--ag2-insp-w));
    }

    html body.ag2.ag2-insp-open #ag2-title {
        max-width: calc(100vw - var(--ag2-sheld-left) - var(--ag2-sheld-right) - var(--ag2-insp-cover) - var(--ag2-tools-w, 232px) - 30px);
    }

    html body.ag2.ag2-insp-open #ag2-shell .ag2-insp-toggle {
        background: var(--ag2-f3);
        color: var(--ag2-l1);
    }

    /* Closed, or opened by ST before the shell adopted it (NavLockOn re-open at start):
       not shown at all. */
    html body.ag2:not(.ag2-insp-open):not(#_):not(#__) #right-nav-panel {
        display: none !important;
        /* R1: ST's running `display` transition would keep it painted (see “no native flash”) */
        transition: none !important;
        animation: none !important;
    }

    html body.ag2.ag2-insp-open:not(#_):not(#__) #right-nav-panel.openDrawer {
        display: flex !important;
        flex-direction: column;
        position: fixed !important;
        top: var(--ag2-inset) !important;
        bottom: var(--ag2-inset) !important;
        right: var(--ag2-inset) !important;
        left: auto !important;
        width: var(--ag2-insp-w) !important;
        min-width: 0 !important;
        max-width: none !important;
        height: auto !important;
        min-height: 0 !important;
        max-height: none !important;
        margin: 0 !important;
        padding: 0 !important;
        overflow: hidden !important;
        border: 0 !important;
        border-radius: var(--ag2-r-panel) !important;
        background: var(--ag2-mat-side) !important;
        -webkit-backdrop-filter: var(--ag2-blur-side) !important;
        backdrop-filter: var(--ag2-blur-side) !important;
        box-shadow: var(--ag2-rim), var(--ag2-sh2) !important;
        color: var(--ag2-l1);
        font-size: var(--ag2-fs-body);
        opacity: 1 !important;
        animation: ag2-insp-in var(--ag2-dur-panel) var(--ag2-ease-sheet);
    }

    @keyframes ag2-insp-in {
        /* Opaque throughout to mask ST's editor; preserve the verified 16px entry. */
        from { transform: translateX(16px); }
        to { transform: none; }
    }

    /* medium: floats over the chat, so a deeper shadow separates it (§4) */
    @media (max-width: 1359px) {
        html body.ag2.ag2-insp-open:not(#_):not(#__) #right-nav-panel.openDrawer {
            box-shadow: var(--ag2-rim), var(--ag2-sh3) !important;
        }
    }

    /* ST's own chrome of the panel (drag grip, lock, list button, hot swaps, name tab,
       token line) — the shell head replaces it; ST still updates it unseen. */
    html body.ag2.ag2-insp-open:not(#_):not(#__) #right-nav-panel > :is(#right-nav-panelheader, #CharListButtonAndHotSwaps, #rm_PinAndTabs) {
        display: none !important;
    }

    /* ST's blocks scroll inside .scrollableInner; only the vetted one shows */
    html body.ag2.ag2-insp-open:not(#_):not(#__) #right-nav-panel > .scrollableInner {
        flex: 1 1 auto;
        min-height: 0;
        height: auto !important;
        margin: 0 !important;
        padding: 0 12px 14px !important;
        overflow-x: hidden !important;
        overflow-y: auto !important;
        overscroll-behavior: contain;
        background: none !important;
        -webkit-mask-image: linear-gradient(to bottom, #000 calc(100% - 18px), transparent);
        mask-image: linear-gradient(to bottom, #000 calc(100% - 18px), transparent);
