    html body.ag2.ag2-insp-open:not(#_):not(#__) #right-nav-panel:is([data-ag2-insp="group"][data-menu-type="group_edit"], [data-ag2-insp="group_create"][data-menu-type="group_create"]) #rm_group_chats_block {
