        padding: 12px 14px !important;
        border: 0 !important;
        border-radius: var(--ag2-r-card) !important;
        background: var(--ag2-f3) !important;
        box-shadow: none !important;
        font-size: var(--ag2-fs-sub);
    }

    /* header row: kill ST's 348° gradient bar, its border/radius/shadow and hover filter */
    html body.ag2.ag2-insp-open:not(#_):not(#__) #right-nav-panel #spoiler_free_desc > .inline-drawer-header {
        box-sizing: border-box;
        align-items: center !important;
        gap: 8px;
        min-height: 24px;
        margin: 0 !important;
        padding: 0 !important;
        border: 0 !important;
        border-radius: 0 !important;
        background: none !important;
        background-image: none !important;
        box-shadow: none !important;
        filter: none !important;
    }

    html body.ag2.ag2-insp-open:not(#_):not(#__) #right-nav-panel #spoiler_free_desc > .inline-drawer-header:hover {
        background: none !important;
        filter: none !important;
    }

    /* the label line (ST's #creators_notes_div.title_restorable) → group title, left */
    html body.ag2.ag2-insp-open:not(#_):not(#__) #right-nav-panel #spoiler_free_desc #creators_notes_div {
        display: flex !important;
        flex: 1 1 auto;
        align-items: center !important;
        gap: 6px;
