        padding: 0 !important;
        border: 0 !important;
        border-radius: var(--ag2-r-ctl) !important;
        background: none !important;
        box-shadow: none !important;
        color: var(--ag2-l2) !important;
        filter: none !important;
        font-size: 13px !important;
    }

    html body.ag2.ag2-insp-open:not(#_):not(#__) #right-nav-panel #spoiler_free_desc > .inline-drawer-header .menu_button:hover {
        background: var(--ag2-f2) !important;
        color: var(--ag2-l1) !important;
    }

    /* the drawer chevron: ST's circled icon at 22.5px → a plain 12px l3 chevron */
    html body.ag2.ag2-insp-open:not(#_):not(#__) #right-nav-panel #spoiler_free_desc .inline-drawer-icon {
        flex: none;
        margin: 0 0 0 2px !important;
        color: var(--ag2-l3) !important;
        filter: none !important;
        font-size: 12px !important;
