    /* content: ST's 1px bordered black box → plain AG2 body text on the card */
    html body.ag2.ag2-insp-open:not(#_):not(#__) #right-nav-panel #spoiler_free_desc > .inline-drawer-content {
        margin: 0 !important;
        padding: 0 !important;
