    /* ST's floating panels (作者注释 / CFG / Logprobs) keep their own nodes and
       behaviour; placed left of the open inspector, else under the tool capsule
       (§5.6). Full AG2 glass header, controls, cards and 180ms entry motion (S1/S3). */
    html body.ag2:not(#_):not(#__) :is(#floatingPrompt, #cfgConfig, #logprobsViewer) {
        position: fixed !important;
        top: calc(var(--ag2-inset) + 54px) !important;
        right: var(--ag2-inset) !important;
        left: auto !important;
        bottom: auto !important;
        flex-direction: column !important;
        gap: 0 !important;
        box-sizing: border-box !important;
        width: var(--ag2-insp-w) !important;
        min-width: 0 !important;
        max-width: calc(100vw - var(--ag2-sheld-left) - var(--ag2-inset) * 2) !important;
        height: auto !important;
        max-height: calc(100dvh - var(--ag2-inset) * 2 - 54px) !important;
        margin: 0 !important;
        padding: 0 !important;
        overflow: hidden !important;
        border: 0 !important;
        border-radius: var(--ag2-r-panel) !important;
        background: var(--ag2-mat-side) !important;
        -webkit-backdrop-filter: var(--ag2-blur-side) !important;
        backdrop-filter: var(--ag2-blur-side) !important;
        box-shadow: var(--ag2-rim), var(--ag2-sh3) !important;
        color: var(--ag2-l1) !important;
        font-size: var(--ag2-fs-sub) !important;
        line-height: 1.45;
        --mainFontSize: 13.5px;
        animation: ag2-float-in 180ms var(--ag2-ease-sheet);
    }

    html body.ag2.no-blur:not(#_):not(#__) :is(#floatingPrompt, #cfgConfig, #logprobsViewer) {
        background: var(--ag2-solid-side) !important;
        -webkit-backdrop-filter: none !important;
        backdrop-filter: none !important;
    }

    @keyframes ag2-float-in {
        from { opacity: 0; transform: translateX(8px) scale(0.985); }
        to { opacity: 1; transform: none; }
    }

    /* ST animates discrete display on drawers. An exclusive inspector must leave the
       paint tree immediately when hidden, rather than overlapping its replacement. */
    html body.ag2:not(#_):not(#__) #movingDivs > .drawer-content {
        transition-property: opacity !important;
        transition-behavior: normal !important;
    }

    html body.ag2.ag2-insp-open:not(#_):not(#__) :is(#floatingPrompt, #cfgConfig, #logprobsViewer) {
        top: var(--ag2-inset) !important;
        right: calc(var(--ag2-inset) * 2 + var(--ag2-insp-w)) !important;
        max-height: calc(100dvh - var(--ag2-inset) * 2) !important;
    }

    /* --- S1 · Secondary floating panels & popups: header chrome + AG2 controls --- */
    /* Hide ST's native drag grip, maximize button and redundant collapse toggle */
    html body.ag2:not(#_):not(#__) #movingDivs > .drawer-content :is(.drag-grabber, .inline-drawer-maximize, #logprovsViewerBlockToggle) {
        display: none !important;
    }

    /* Standard Apple panel header bar (46px, title left, 28px round × button right) */
    html body.ag2:not(#_):not(#__) :is(#floatingPrompt > .panelControlBar, #cfgConfig > .panelControlBar, #logprobsViewer > .logprobs_panel_header) {
        position: static !important;
        display: flex !important;
        flex: none !important;
        align-items: center !important;
        justify-content: space-between !important;
        box-sizing: border-box !important;
        width: 100% !important;
        min-height: 46px !important;
        margin: 0 !important;
        padding: 10px 12px 8px 16px !important;
        border: 0 !important;
        background: none !important;
        box-shadow: inset 0 -0.5px 0 var(--ag2-sep) !important;
    }

    html body.ag2:not(#_):not(#__) #floatingPrompt > .panelControlBar::before {
        content: "作者注释";
        color: var(--ag2-l1);
        font-size: 15px;
        font-weight: 650;
        line-height: 1.3;
    }

    html body.ag2:not(#_):not(#__) #cfgConfig > .panelControlBar::before {
        content: "CFG 引导缩放";
        color: var(--ag2-l1);
        font-size: 15px;
        font-weight: 650;
        line-height: 1.3;
    }

    html body.ag2:not(#_):not(#__) #logprobsViewer > .logprobs_panel_header > .logprobs_panel_header {
        margin: 0 !important;
        padding: 0 !important;
        color: var(--ag2-l1) !important;
        font-size: 15px !important;
        font-weight: 650 !important;
        line-height: 1.3 !important;
    }

    html body.ag2:not(#_):not(#__) #logprobsViewer > .logprobs_panel_header > .logprobs_panel_header b {
        font-weight: 650 !important;
    }

    html body.ag2:not(#_):not(#__) #logprobsViewer > .logprobs_panel_header > .logprobs_panel_controls {
        display: flex !important;
        align-items: center !important;
        margin: 0 0 0 auto !important;
        padding: 0 !important;
    }

    html body.ag2:not(#_):not(#__) :is(#ANClose, #CFGClose, #logprobsViewerClose),
    html body.ag2:not(#_):not(#__) #movingDivs > .drawer-content .floating_panel_close {
        display: inline-flex !important;
        flex: none !important;
        align-items: center !important;
        justify-content: center !important;
        width: 28px !important;
        height: 28px !important;
