/* == 5.7 · Command palette (§5.7, design 04b) == */
/* Native <dialog id="ag2-palette"> opened with showModal(): it lives in the top layer, so no
   z-index is needed and it sits above ST's z-3005 panels and old-style popups (§9.2 #10).
   Material = window material (one blur layer; the backdrop dims without blur). */

html body.ag2:not(#_):not(#__) #ag2-palette {
    position: fixed;
    inset: clamp(56px, 13vh, 120px) 0 auto 0;
    display: none;
    flex-direction: column;
    width: min(640px, calc(100vw - 24px));
    max-width: none;
    max-height: min(560px, calc(100dvh - clamp(56px, 13vh, 120px) - 24px));
    margin: 0 auto;
    padding: 0;
    overflow: hidden;
    border: 0;
    border-radius: var(--ag2-r-panel);
    background: var(--ag2-mat-window);
    -webkit-backdrop-filter: var(--ag2-blur-window);
    backdrop-filter: var(--ag2-blur-window);
    box-shadow: var(--ag2-rim), var(--ag2-sh3);
    color: var(--ag2-l1);
    font: var(--ag2-fs-body) / 1.4 var(--ag2-font);
    animation: ag2-pop var(--ag2-dur) var(--ag2-ease);
}

html body.ag2:not(#_):not(#__) #ag2-palette[open] {
    display: flex;
}

/* dim only: a second full-screen blur would exceed the §7 budget */
html body.ag2 #ag2-palette::backdrop {
    background: rgba(0, 0, 0, 0.32);
}

/* Toasts stay in ST's chosen topmost dialog, but participate in layout. Only a
   non-empty container takes space; long/multiple notices scroll in a bounded slot. */
html body.ag2:not(#_):not(#__) :is(dialog.popup, dialog#ag2-palette) > #toast-container {
    position: static !important;
    inset: auto !important;
    order: -1;
    flex: 0 1 auto;
    min-height: 0;
    max-height: min(160px, 25dvh);
    width: auto !important;
    margin: 8px !important;
    overflow: auto;
    pointer-events: auto;
    text-align: left;
}
html body.ag2:not(#_):not(#__) :is(dialog.popup, dialog#ag2-palette) > #toast-container:empty {
    display: none !important;
}
html body.ag2:not(#_):not(#__) :is(dialog.popup, dialog#ag2-palette) > #toast-container > div {
    width: 100% !important;
    max-width: none !important;
    margin: 0 0 6px !important;
    overflow-wrap: anywhere;
}
html body.ag2:not(#_):not(#__) :is(dialog.popup, dialog#ag2-palette) > #toast-container > div:last-child {
    margin-bottom: 0 !important;
}
html body.ag2:not(#_):not(#__) dialog.popup:has(> #toast-container:not(:empty)) {
    min-height: 0;
}
html body.ag2:not(#_):not(#__) dialog.popup:has(> #toast-container:not(:empty)) > .popup-body {
    min-height: 0;
    flex: 1 1 auto;
}

/* --- field row: icon · input · esc --- */
html body.ag2:not(#_):not(#__) #ag2-palette .ag2-pal-field {
    display: flex;
    flex: none;
    align-items: center;
    gap: 10px;
    height: 54px;
    padding: 0 16px 0 18px;
    border-bottom: 0.5px solid var(--ag2-sep);
    color: var(--ag2-l3);
}

/* ST styles every input (font, colour) and AG2 resets text_pole: undo both here */
html body.ag2:not(#_):not(#__) #ag2-palette .ag2-pal-input {
    flex: 1;
    min-width: 0;
    height: 100%;
    margin: 0;
    padding: 0;
    border: 0 !important;
    outline: none !important;
    box-shadow: none !important;
    background: transparent !important;
    color: var(--ag2-l1) !important;
    font: 400 18px/1.2 var(--ag2-font) !important;
}

html body.ag2:not(#_):not(#__) #ag2-palette .ag2-pal-input::placeholder {
    color: var(--ag2-l3);
}

/* ST's global kbd is a light keycap; the palette's are dark chips (as in the sidebar) */
html body.ag2:not(#_):not(#__) #ag2-palette kbd {
    display: inline-block;
    min-width: 18px;
    margin: 0 2px 0 0;
    padding: 1px 5px;
    border: 0;
    border-radius: 5px;
    background: var(--ag2-f4);
    box-shadow: inset 0 0 0 0.5px var(--ag2-sep-strong);
    color: var(--ag2-l2);
    font: 600 11px/16px var(--ag2-font);
    text-align: center;
}

/* --- results --- */
html body.ag2:not(#_):not(#__) #ag2-palette .ag2-pal-list {
    flex: 1 1 auto;
    min-height: 0;
    padding: 4px 8px 8px;
    overflow: hidden auto;
    overscroll-behavior: contain;
    scrollbar-width: thin;
}

html body.ag2:not(#_):not(#__) #ag2-palette .ag2-pal-head {
    padding: 12px 12px 5px;
    color: var(--ag2-l3);
    font-size: var(--ag2-fs-section);
    font-weight: 620;
}

html body.ag2:not(#_):not(#__) #ag2-palette .ag2-pal-row {
    display: flex;
    align-items: center;
    gap: 11px;
    min-height: 40px;
    padding: 5px 10px;
    border-radius: var(--ag2-r-row);
    cursor: pointer;
    user-select: none;
}

/* selected row: whole row in the accent colour (§5.7) */
html body.ag2:not(#_):not(#__) #ag2-palette .ag2-pal-row.ag2-sel {
    background: var(--ag2-accent);
    color: #fff;
}

html body.ag2:not(#_):not(#__) #ag2-palette .ag2-pal-tile,
html body.ag2:not(#_):not(#__) #ag2-palette .ag2-pal-av {
    display: grid;
    flex: none;
    place-items: center;
    width: 26px;
    height: 26px;
    border-radius: 7px;
    color: #fff;
}

html body.ag2:not(#_):not(#__) #ag2-palette .ag2-pal-tile {
    box-shadow: inset 0 0.5px 0 rgba(255, 255, 255, 0.25);
}

html body.ag2:not(#_):not(#__) #ag2-palette .ag2-pal-tile svg {
    stroke-width: 2;
}

html body.ag2:not(#_):not(#__) #ag2-palette .ag2-pal-av {
    border-radius: 50%;
    object-fit: cover;
    background: var(--ag2-f3);
}

html body.ag2:not(#_):not(#__) #ag2-palette .ag2-pal-txt {
    display: flex;
    flex: 1;
    align-items: baseline;
    gap: 9px;
    min-width: 0;
}

html body.ag2:not(#_):not(#__) #ag2-palette .ag2-pal-title {
    flex: none;
    max-width: 62%;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    font-weight: 500;
}

html body.ag2:not(#_):not(#__) #ag2-palette .ag2-pal-sub {
    flex: 1;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    color: var(--ag2-l3);
    font-size: var(--ag2-fs-foot);
}

/* matched characters: bold + underlined (§5.7) */
html body.ag2:not(#_):not(#__) #ag2-palette .ag2-pal-m {
    font-weight: 700;
    text-decoration: underline;
    text-decoration-thickness: 1.5px;
    text-underline-offset: 2.5px;
}

html body.ag2:not(#_):not(#__) #ag2-palette .ag2-pal-hint {
    display: inline-flex;
    flex: none;
    align-items: center;
    color: var(--ag2-l3);
}

/* ↵ glyph only on the selected row */
html body.ag2:not(#_):not(#__) #ag2-palette .ag2-pal-enter {
