/* == 5.8b · ST's native popups · toastr · movingDivs (R2b) == */
/* §5.8: ST's own dialogs and toasts are made part of AG2. Only their LOOK changes — the
   open/close logic, the z-order and every control stay ST's (§9.2 #10: these layers sit at
   z 4000–999999, above the shell; we never touch z-index or behaviour). Materials: one blur
   layer per surface; full-screen dim backdrops carry NO blur (§7 budget — r1 counts a
   >60%-viewport blurred layer as a blur frame). */

/* --- modern dialog.popup (scripts/popup.js: persona connections, confirmations, …)
       ST: 500px, radius 10, blur-tint bg, 14px black glow. AG2: centred card, radius 22,
       window material, rim + sh3, no border. The card keeps its one blur; the ::backdrop
       only dims (a second full-screen blur would blow the budget). */
html body.ag2:not(#_):not(#__) dialog.popup {
    width: min(520px, calc(100dvw - 24px));
    max-width: calc(100dvw - 24px);
    max-height: calc(100dvh - 32px);
    padding: 16px 20px 18px;
    border: 0 !important;
    border-radius: var(--ag2-r-panel) !important;
    background: var(--ag2-mat-window) !important;
    -webkit-backdrop-filter: var(--ag2-blur-window);
    backdrop-filter: var(--ag2-blur-window);
    box-shadow: var(--ag2-rim), var(--ag2-sh3) !important;
    color: var(--ag2-l1);
    font: var(--ag2-fs-body) / 1.5 var(--ag2-font);
}

html body.ag2.no-blur:not(#_):not(#__) dialog.popup {
    background: var(--ag2-solid-window) !important;
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
}

html body.ag2:not(#_):not(#__) dialog.popup .popup-content {
    margin-top: 6px;
    padding: 0 2px;
    overflow-wrap: anywhere;
}

html body.ag2:not(#_):not(#__) dialog.popup .popup-content :is(h3, .popup-header) {
    margin: 0 0 4px;
    color: var(--ag2-l1);
    font-size: 16px;
    font-weight: 650;
    text-align: center;
}

html body.ag2:not(#_):not(#__) dialog.popup .multiline {
    color: var(--ag2-l2);
    font-size: var(--ag2-fs-sub);
    line-height: 1.6;
}

/* persona avatars inside the popup: AG2 selection ring instead of ST's 2px outline */
html body.ag2:not(#_):not(#__) dialog.popup .persona-list .avatar,
html body.ag2:not(#_):not(#__) dialog.popup .avatars_inline .avatar {
