}

html body.ag2:not(#_):not(#__) dialog.popup .persona-list .avatar.is_active,
html body.ag2:not(#_):not(#__) dialog.popup .persona-list .avatar:hover {
    outline: none !important;
    box-shadow: inset 0 0 0 2px var(--ag2-accent) !important;
}

html body.ag2:not(#_):not(#__) dialog.popup .avatar img {
    border-radius: 12px;
}

html body.ag2:not(#_):not(#__) dialog.popup .popup-input {
    margin-top: 10px;
    border: 0 !important;
    border-radius: var(--ag2-r-ctl) !important;
    background: var(--ag2-f4) !important;
    box-shadow: inset 0 0 0 0.5px var(--ag2-sep-strong) !important;
    color: var(--ag2-l1) !important;
    font-size: var(--ag2-fs-sub);
}

html body.ag2:not(#_):not(#__) dialog.popup .popup-inputs label span {
    color: var(--ag2-l3);
    opacity: 1;
}

/* buttons: primary = accent capsule, secondary/custom = filled capsule (§5.8) */
html body.ag2:not(#_):not(#__) dialog.popup .popup-controls {
    gap: 12px;
    margin-top: 14px;
}

html body.ag2:not(#_):not(#__) dialog.popup .popup-controls .menu_button {
    min-height: 36px;
    margin: 0;
    padding: 0 20px;
    border: 0 !important;
    border-radius: var(--ag2-r-full) !important;
    background: var(--ag2-f2) !important;
    color: var(--ag2-l1) !important;
    filter: none !important;
    font-size: var(--ag2-fs-sub);
    font-weight: 600;
    white-space: nowrap;
    transition: background-color var(--ag2-dur) ease, filter var(--ag2-dur) ease;
}

html body.ag2:not(#_):not(#__) dialog.popup .popup-controls .menu_button:hover {
    background: var(--ag2-f1) !important;
}

html body.ag2:not(#_):not(#__) dialog.popup .popup-controls .popup-button-ok {
    background: var(--ag2-accent) !important;
    color: #fff !important;
}

html body.ag2:not(#_):not(#__) dialog.popup .popup-controls .popup-button-ok:hover {
    background: var(--ag2-accent-hover) !important;
}

html body.ag2:not(#_):not(#__) dialog.popup .popup-button-close {
