}

html body.ag2:not(#_):not(#__) dialog.popup::backdrop {
    background: rgba(0, 0, 0, 0.42);
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
}

/* §5.8 / §18c: Apple sheet scale + fade instead of ST's own pop-in */
@keyframes ag2-popup-in {
    from { opacity: 0; transform: scale(0.96); }
    to { opacity: 1; transform: none; }
}

@keyframes ag2-popup-out {
    from { opacity: 1; transform: none; }
    to { opacity: 0; transform: scale(0.97); }
}

html body.ag2:not(#_):not(#__) dialog.popup[opening] {
    animation: ag2-popup-in var(--ag2-dur) var(--ag2-ease);
}

html body.ag2:not(#_):not(#__) dialog.popup[closing] {
    animation: ag2-popup-out var(--ag2-dur) var(--ag2-ease);
}

html body.ag2:not(#_):not(#__) dialog.popup[opening]::backdrop {
    animation: none;
}

