/* == 5.9 · Phone (§5.9, §4, §9.2 #11; design 05) == */
/* body.ag2-phone = width ≤1000px (index.js matchMedia, the same query as these blocks), never
   the UA. Every rule sits in the media query AND under .ag2-phone, so 1000 / 1001 can never
   mix the two layouts. ST's mobile-styles.css (and its iOS-only @supports block, which
   Chromium cannot emulate) write many plain and some !important rules for this width; the
   overrides below carry !important and the :not(#_):not(#__) weight.
   Pages (body[data-ag2-ph], shell/phone.js): list = #ag2-sidebar as a full-screen 大标题 list
   + tab bar; chat = #sheld + capsules ‹ · title · ⋯. All of them live in #ag2-shell, outside
   #sheld (a horizontal swipe inside #sheld swipes the last reply). Settings = bottom sheet
   (#ag2-settings.ag2-set-phone), inspector = full-screen sheet. Keyboard: --ag2-vvh/--ag2-vvt
   from visualViewport. Blur budget (§7): chat page 4 (three capsules + composer), list 1
   (tab bar; the list itself is opaque). */

@media (max-width: 1000px) {
    /* (the ID weight also beats §5.5c's [data-ag2-anchors] head height) */
    html body.ag2.ag2-phone:not(#_):not(#__) {
        --ag2-safe-t: env(safe-area-inset-top, 0px);
        --ag2-safe-b: env(safe-area-inset-bottom, 0px);
        --ag2-safe-l: env(safe-area-inset-left, 0px);
        --ag2-safe-r: env(safe-area-inset-right, 0px);
        /* visible height: the visual viewport (keyboard aware) once phone.js has run */
        --ag2-ph-h: var(--ag2-vvh, 100dvh);
        --ag2-ph-cap-top: calc(var(--ag2-safe-t) + 6px);
        /* composer / tab bar distance from the bottom edge: the home indicator, or 8px
           while the keyboard covers it (body.ag2-kb) */
        --ag2-ph-bottom: max(var(--ag2-safe-b), 10px);
        --ag2-ph-bg: linear-gradient(180deg, rgb(24, 24, 29), rgb(12, 12, 15) 70%);
        --ag2-sheld-left: 0px;
        --ag2-sheld-right: 0px;
        --ag2-fade-top: calc(var(--ag2-safe-t) + 56px);
        /* settings sheet: the window variables of §5.5 describe the sheet, so the ST drawer
           rule positions the open drawer under the sheet head unchanged */
        --ag2-sheet-top: calc(var(--ag2-safe-t) + 10px);
        --ag2-win-x: 0px;
        --ag2-win-w: 100vw;
        --ag2-win-y: var(--ag2-sheet-top);
        --ag2-win-h: calc(var(--ag2-ph-h) - var(--ag2-sheet-top));
        --ag2-set-nav: 0px;
        --ag2-set-head: 56px;
    }

    html body.ag2.ag2-phone.ag2-kb:not(#_):not(#__) {
        --ag2-ph-bottom: 8px;
    }

    /* tablets in portrait / narrow windows (641–1000px) still get the phone layout (§4: width
       only); sheets stay phone-wide and centred instead of stretching edge to edge */
    @media (min-width: 641px) {
        html body.ag2.ag2-phone:not(#_):not(#__) {
            --ag2-win-w: 600px;
            --ag2-win-x: calc((100vw - 600px) / 2);
        }
    }

    /* <html> is the containing block of every fixed element (ST: translateZ(0)), and with
       ST's phone `body { position: fixed }` it has no in-flow content → 0px tall. Give it
       the viewport height so inset / bottom-anchored layers (#ag2-shell, the sheet dim,
       the tab bar) measure from the screen, as on desktop. */
    html:has(> body.ag2.ag2-phone:not(#_):not(#__)) {
        height: 100%;
    }

    /* --- chat page: #sheld fills the visual viewport (follows the iOS keyboard) --- */
    html body.ag2.ag2-phone:not(#_):not(#__) #sheld {
        top: var(--ag2-vvt, 0px) !important;
        bottom: auto !important;
        left: 0 !important;
        right: 0 !important;
        width: 100vw !important;
        min-width: 0 !important;
        max-width: none !important;
        height: var(--ag2-ph-h) !important;
        min-height: 0 !important;
        max-height: none !important;
        margin: 0 !important;
        padding: 0 !important;
        border: 0 !important;
        transition: none;
    }

    /* list page (or nothing open): the chat stays laid out but leaves the a11y tree and
       the blur count once the list has slid over it */
    html body.ag2.ag2-phone:is(:not([data-ag2-ph="chat"]), .ag2-welcome):not(#_):not(#__) #sheld {
        visibility: hidden !important;
        transition: visibility 0s linear var(--ag2-dur-panel);
    }

    html body.ag2.ag2-phone:not(#_):not(#__) #chat {
        padding-top: calc(var(--ag2-safe-t) + 62px) !important;
        /* the 外观 › 行宽 column still applies when the phone layout is wide (tablet) */
        padding-left: max(14px, var(--ag2-safe-l), calc((100% - var(--ag2-read-width)) / 2)) !important;
        padding-right: max(14px, var(--ag2-safe-r), calc((100% - var(--ag2-read-width)) / 2)) !important;
        padding-bottom: calc(var(--ag2-dock-h, 112px) + 36px) !important;
        /* The measured dock includes QR and a growing composer. Fade only the last
           24px before its top; bottom padding keeps the final line fully readable. */
        -webkit-mask-image: linear-gradient(to bottom, transparent 0, #000 var(--ag2-fade-top), #000 calc(100% - var(--ag2-dock-h, 112px) - 24px), transparent calc(100% - var(--ag2-dock-h, 112px)));
        mask-image: linear-gradient(to bottom, transparent 0, #000 var(--ag2-fade-top), #000 calc(100% - var(--ag2-dock-h, 112px) - 24px), transparent calc(100% - var(--ag2-dock-h, 112px)));
        border: 0 !important;
    }

    /* meta line: on a 360px column the model name shrinks (ellipsis) instead of pushing
       the meta over the action buttons (小白X adds one there) */
    html body.ag2.ag2-phone:not(#_):not(#__) #chat .mes {
        grid-template-columns:
            [outer] var(--ag2-mes-ol) [card] var(--ag2-mes-pl)
            [in sw] auto [cnt] auto [swr] auto [btns] auto [gap] minmax(0, 1fr)
            [model] minmax(0, auto) [tok] auto [tim] auto [pr] var(--ag2-mes-pr) [end];
    }

    /* the buttons keep their 30px: otherwise the row's min-content shrinks them and the
       meta column paints over the last one */
    html body.ag2.ag2-phone:not(#_):not(#__) #chat .mes .mes_buttons {
        min-width: max-content;
    }

    html body.ag2.ag2-phone:not(#_):not(#__) #chat .mes:not(.smallSysMes) .mes_buttons:has(> .extraMesButtons.visible),
    html body.ag2.ag2-phone.expandMessageActions:not(#_):not(#__) #chat .mes:not(.smallSysMes) .mes_buttons {
        min-width: 0;
    }

    html body.ag2.ag2-phone:not(#_):not(#__) #chat .mes .mes_buttons > * {
        flex-shrink: 0;
    }

    /* menus: 44px rows on touch (§5.9) */
    html body.ag2.ag2-phone:not(#_):not(#__) :is(#ag2-shell, #ag2-layer) .ag2-menu-item {
        min-height: 44px;
        font-size: 15px;
    }

    /* composer: full width minus 10px gutters, above the home indicator / keyboard */
    html body.ag2.ag2-phone:not(#_):not(#__) #form_sheld {
        width: min(calc(100% - 20px - var(--ag2-safe-l) - var(--ag2-safe-r)), calc(var(--ag2-read-width) + 40px)) !important;
        padding: 0 0 var(--ag2-ph-bottom) !important;
    }

    html body.ag2.ag2-phone:not(#_):not(#__) #send_form #nonQRFormItems {
        min-height: 56px !important;
        padding: 6px !important;
        border-radius: 28px !important;
    }

    /* touch targets ≥44pt (§5.9) */
    html body.ag2.ag2-phone:not(#_):not(#__) :is(#ag2-plus, #send_form #send_but, #send_form #mes_stop) {
        width: 44px !important;
        min-width: 44px !important;
        height: 44px !important;
        border-radius: 22px !important;
    }

    html body.ag2.ag2-phone:not(#_):not(#__) #send_form :is(#leftSendForm, #rightSendForm) {
        min-height: 44px !important;
    }

    html body.ag2.ag2-phone:not(#_):not(#__) #leftSendForm > :not(#ag2-plus),
    html body.ag2.ag2-phone:not(#_):not(#__) #rightSendForm > :not(#ag2-model):not(#send_but):not(#mes_stop) {
        width: 44px !important;
        min-width: 44px !important;
        height: 44px !important;
        border-radius: 22px !important;
    }

    html body.ag2.ag2-phone:not(#_):not(#__) #send_form #send_textarea {
        font-size: 16px !important; /* <16px makes iOS zoom the page on focus */
    }

    /* QR capsules: 40px (design 05 draws small chips; the row clips overflow, so no larger
       invisible hit area is possible) */
    html body.ag2.ag2-phone:not(#_):not(#__) :is(#qr--bar, #qr-bar) :is(.qr--button, .menu_button) {
        min-height: 40px !important;
    }

    /* “+ 快速回复” stays a desktop affordance (design 05 shows the QR row only) */
    html body.ag2.ag2-phone:not(#_):not(#__) #ag2-qr-add {
        display: none !important;
    }

    /* --- capsules: ‹ back · title · ⋯ (design 05 left) --- */
    html body.ag2.ag2-phone:not(#_):not(#__) #ag2-shell .ag2-cap {
        top: var(--ag2-ph-cap-top);
        transition: none;
    }

    html body.ag2.ag2-phone:not(#_):not(#__) #ag2-shell .ag2-ph-round {
        display: inline-flex;
        justify-content: center;
        width: 44px;
        padding: 0;
        color: var(--ag2-l1);
    }

    html body.ag2.ag2-phone:not(#_):not(#__) #ag2-ph-back {
        left: calc(10px + var(--ag2-safe-l));
    }

    html body.ag2.ag2-phone:not(#_):not(#__) #ag2-ph-more {
        right: calc(10px + var(--ag2-safe-r));
