/* == 13 · Ported fixes (apple-theme.css §15m, §19b, §17a) == */
/* Under AG2 ST's own panels still render with the theme JSON's blur strength and
   none of AG Dark's fixes; these two keep the §4.6 regression at zero until the
   P2 settings window restyles the panels. */

/* §7 / §18a: a blurred panel never contains another blurred layer (ST gives the
   formatting notice, background tabs and tile toggles their own blur). */
html body.ag2:not(#_):not(#__) :is(.drawer-content, #character_popup, #completion_prompt_manager_popup) *,
html body.ag2:not(#_):not(#__) .bg_example .mobile-only-menu-toggle {
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
}

/* §19b: text buttons keep their label on one line (“重置”, Extras “连接” were
   squeezed into one-glyph-per-line pills). :not(:empty) leaves glyph-only buttons round. */
html body.ag2:not(#_):not(#__) .menu_button:not(:empty):not(.mes_text *),
html body.ag2:not(#_):not(#__) .menu_button_icon:not(:empty):not(.mes_text *),
html body.ag2:not(#_):not(#__) .api_button {
    white-space: nowrap !important;
    flex-shrink: 0 !important;
    max-width: 100%;
}

html body.ag2:not(#_):not(#__) .extensions_url_block {
    flex: 0 0 auto !important;
}

/* AG Dark §17a · Stable viewport: 小白X's closed quick-launcher is parked below the
   fold; <html> is the fixed containing block (translateZ), so it made the root ~230px
   scrollable and any scrollIntoView() (a click on a control) pushed the whole UI up.
   Layout containment keeps the root exactly one viewport tall. */
html:has(> body.ag2:not(#_):not(#__)) {
    contain: layout;
}

/* R3a task 1: phone ⋯/× glyph swap animation (§5.9). */
@keyframes ag2-ph-more-in {
    from { opacity: 0; transform: rotate(-90deg) scale(0.72); }
    to { opacity: 1; transform: none; }
}

/* == 13.1 · Shared native controls and gesture state == */
/* Gesture state is diagnostic/non-inherited; presentation translates only its surfaces. */
@property --ag2-sheet-dy {
    syntax: "<length>";
    inherits: false;
    initial-value: 0px;
}

/* Only native form controls opt into dark UA chrome. A page-wide scheme changes
   the embedding boundary and makes light/transparent third-party iframes opaque.
   Keep ST's page/content scheme intact, including message cards and embedded SVG. */
html body.ag2:not(#_):not(#__) :is(#ag2-settings, .drawer-content, #character_popup, dialog.popup, #send_form) :is(input, select, textarea) {
    color-scheme: dark;
}

/* Real scrolling surfaces only: leave the intentionally hidden QR / anchor bars alone.
   Firefox uses the standard path. WebKit's path resets BOTH standard properties so its
   thumb/track/button rules actually paint instead of being overridden by thin/auto. */
html body.ag2:not(#_):not(#__) :is(#ag2-pal-list, .ag2-side-list, .ag2-set-body, .ag2-set-nav, .drawer-content, .scrollableInner, [name="floatingPromptHolder"], [name="cfgConfigHolder"], .logprobs_panel_content, #character_popup, #completion_prompt_manager_popup, textarea, .select2-results__options, .popup-content, #toast-container) {
    scrollbar-width: thin !important;
    scrollbar-color: rgba(235,235,245,.3) transparent !important;
}
@supports selector(::-webkit-scrollbar) {
    html body.ag2:not(#_):not(#__) :is(#ag2-pal-list, .ag2-side-list, .ag2-set-body, .ag2-set-nav, .drawer-content, .scrollableInner, [name="floatingPromptHolder"], [name="cfgConfigHolder"], .logprobs_panel_content, #character_popup, #completion_prompt_manager_popup, textarea, .select2-results__options, .popup-content, #toast-container) {
        scrollbar-width: auto !important;
        scrollbar-color: auto !important;
    }
    html body.ag2:not(#_):not(#__) :is(#ag2-pal-list, .ag2-side-list, .ag2-set-body, .ag2-set-nav, .drawer-content, .scrollableInner, [name="floatingPromptHolder"], [name="cfgConfigHolder"], .logprobs_panel_content, #character_popup, #completion_prompt_manager_popup, textarea, .select2-results__options, .popup-content, #toast-container)::-webkit-scrollbar {
        width: 6px;
        height: 6px;
