/* Keep native select semantics/events; only ordinary single-selects opt in. */
@supports (appearance: base-select) {
    /* Explicit standard selectedcontent is supplied only in the active settings page.
       The UA's implicit selected label is not author-styleable in Chromium. */
    html body.ag2:not(#_):not(#__) select > button.ag2-select-button {
        display: block;
        flex: 1;
        min-width: 0;
        width: 100%;
        margin: 0;
        padding: 0;
        border: 0;
        border-radius: 0;
        background: transparent;
        box-shadow: none;
        color: inherit;
        font: inherit;
        text-align: inherit;
    }
    html body.ag2:not(#_):not(#__) select > .ag2-select-button > selectedcontent {
        display: block;
        overflow: hidden;
        white-space: nowrap;
        text-overflow: ellipsis;
    }
    html body.ag2:not(#_):not(#__) :is(#ag2-settings, .drawer-content, #character_popup, dialog.popup) select:not([multiple]):not([size]):not(.select2-hidden-accessible) {
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
    }
    html body.ag2:not(#_):not(#__) :is(#ag2-settings, .drawer-content, #character_popup, dialog.popup) select:not([multiple]):not([size]):not(.select2-hidden-accessible),
    html body.ag2:not(#_):not(#__) :is(#ag2-settings, .drawer-content, #character_popup, dialog.popup) select:not([multiple]):not([size]):not(.select2-hidden-accessible)::picker(select) {
        appearance: base-select !important;
    }
    html body.ag2:not(#_):not(#__) :is(#ag2-settings, #movingDivs > .drawer-content, #character_popup, #completion_prompt_manager_popup, #right-nav-panel) select:not([multiple]):not([size]):not(.select2-hidden-accessible)::picker-icon,
    html body.ag2.ag2-set-open:not(#_):not(#__) :is(#rm_api_block, #left-nav-panel, #AdvancedFormatting, #WorldInfo, #PersonaManagement, #Backgrounds, #user-settings-block, #rm_extensions_block) select:not([multiple]):not([size]):not(.select2-hidden-accessible)::picker-icon {
        display: none; /* existing single chevron stays, including the shell's SVG */
    }
    html body.ag2:not(#_):not(#__) :is(#ag2-settings, .drawer-content, #character_popup, dialog.popup) select:not([multiple]):not([size]):not(.select2-hidden-accessible)::picker(select) {
        box-sizing: border-box;
        margin-block: 5px;
        padding: 5px;
        max-width: calc(100dvw - 24px);
        max-height: min(320px, 50dvh);
        overflow: auto;
        border: 1px solid var(--ag2-sep-strong);
        border-radius: 12px;
        background: var(--ag2-solid-menu);
        color: var(--ag2-l1);
        box-shadow: var(--ag2-sh3);
        scrollbar-width: thin;
        scrollbar-color: rgba(235,235,245,.3) var(--ag2-solid-menu);
    }
    html body.ag2:not(#_):not(#__) :is(#ag2-settings, .drawer-content, #character_popup, dialog.popup) select:not([multiple]):not([size]):not(.select2-hidden-accessible) option {
        min-height: 32px;
        padding: 6px 10px;
        border-radius: 7px;
        background: transparent;
        color: var(--ag2-l1);
        line-height: 1.4;
        white-space: normal;
        overflow-wrap: anywhere;
    }
    html body.ag2:not(#_):not(#__) :is(#ag2-settings, .drawer-content, #character_popup, dialog.popup) select:not([multiple]):not([size]):not(.select2-hidden-accessible) option:checked {
        background: var(--ag2-f2);
    }
    html body.ag2:not(#_):not(#__) :is(#ag2-settings, .drawer-content, #character_popup, dialog.popup) select:not([multiple]):not([size]):not(.select2-hidden-accessible) option:is(:hover, :focus-visible) {
        background: var(--ag2-accent);
        color: #fff;
        outline: 0;
    }
}

/* Native multi-selects are used instead of Select2 on phones. Keep their native
   multi-selection semantics, but give the listbox the same inset field surface. */
html body.ag2:not(#_):not(#__) :is(.drawer-content, #character_popup) select[multiple]:not(.select2-hidden-accessible) {
