    background: var(--ag2-f3) !important;
    box-shadow: inset 0 0 0 0.5px var(--ag2-sep) !important;
    color: var(--ag2-l1) !important;
    font-size: var(--ag2-fs-sub);
}

html body.ag2:not(#_):not(#__) :is(.drawer-content, #character_popup) select[multiple]:not(.select2-hidden-accessible) option {
